    private void Start()
    {
        StringTheoryDiagnostics.EnsureInitialized("game-start");
        StringTheoryDiagnosticsUploadService.Initialize();
        showDiagnosticsConsentPopup = StringTheoryDiagnosticsUploadService.ShouldShowStartupConsentPrompt;
        Application.targetFrameRate = 60;
        ExternalContentBootstrap.EnsureRuntimeContentReady();
        Debug.Log($"[GuitarBridgeServer] Using persistent content folder: {ExternalContentPaths.PersistentRoot}");
        Debug.Log($"[NotesDetector] Start() called on '{gameObject.name}'. autoLaunchNotesDetector={autoLaunchNotesDetector}, enabled={enabled}, activeInHierarchy={gameObject.activeInHierarchy}, platform={Application.platform}");
        miniGameManager = new MiniGameManager();
        miniGameManager.Initialize(ExternalContentPaths.PersistentRoot);
        isRunning = true;
        BuildNoteIndices();
        StartUdpThread();
        EnsureBackingTrackSource();
        EnsureGeneratedSongPlayerInitialized();
        RegisterRuntimeSettings();
        LoadGlobalRuntimeSettingsMetadata();
        LoadGameSaveState();
        LoadHeroModePreferences();
        EnsureToneLabRuntimeComponent();
        EnsureGuitarTunerService();
        WireToneLabRuntimeCallbacks();
        LoadSharedAudioSettingsFromDisk();
        RefreshSharedAudioRoutingCatalogs(refreshToneLabDevices: true, refreshDetectorDevices: true, forcePortAudioRescan: true);
        ApplySharedAudioSettingsToSubsystems(restartDetector: false, restartToneLab: false, refreshCatalogs: false);
        LoadSongLibraryTypePreference();
        InitializeMultiplayerRhythmPlayers();
        RefreshMultiplayerRhythmAvailableDevices();
        StartConfiguredNotesDetectorBackend();
        bool startInMainMenu = true;
        showMainMenu = startInMainMenu;
        mainMenuFlowActive = startInMainMenu;
        isPaused = startInMainMenu;
        LoadTestSong();
        isPaused = startInMainMenu;
        unityToneLabRuntime?.StartBackgroundMonitoring();
        EnsureRenderer();
        SyncAudioToSongTimer(playImmediately: false);
        LogFullDiagnosticsSnapshot("startup-complete", includeEnvironment: true);
        diagnosticsStartupSnapshotCompleted = true;
        QueueAutomaticDiagnosticsUploads("startup-complete");
    }

    private void LogFullDiagnosticsSnapshot(string reason, bool includeEnvironment)
    {
        try
        {
            StringBuilder builder = new StringBuilder();
            if (includeEnvironment)
            {
                builder.AppendLine(StringTheoryDiagnostics.BuildEnvironmentSnapshot());
                builder.AppendLine();
            }

            builder.AppendLine(BuildGameDiagnosticSnapshot());
            if (unityToneLabRuntime != null)
            {
                builder.AppendLine();
                builder.AppendLine(unityToneLabRuntime.BuildAudioDiagnosticSnapshot());
            }

            StringTheoryDiagnostics.LogSnapshot(reason, builder.ToString());
        }
        catch (Exception ex)
        {
            Debug.LogWarning($"[Diagnostics] Failed to build diagnostics snapshot '{reason}': {ex.Message}");
        }
    }

    private void QueueAutomaticDiagnosticsUploads(string reason)
    {
        if (!StringTheoryDiagnosticsUploadService.AutomaticUploadsEnabled)
            return;

        StartCoroutine(AutomaticDiagnosticsUploadSequence(reason));
    }

    private IEnumerator AutomaticDiagnosticsUploadSequence(string reason)
    {
        yield return StringTheoryDiagnosticsUploadService.UploadPreviousSessionIfNeeded();
        yield return StringTheoryDiagnosticsUploadService.UploadCurrentSessionIfNeeded(reason, diagnosticsStartupSnapshotCompleted ? 8f : 20f);
    }

    private string BuildGameDiagnosticSnapshot()
    {
        StringBuilder builder = new StringBuilder();
        builder.AppendLine("Build");
        builder.AppendLine($"  version: {StringTheoryBuildInfo.Version}");
        builder.AppendLine($"  channel: {StringTheoryBuildInfo.Channel}");
        builder.AppendLine($"  diagnosticsSchemaVersion: {StringTheoryBuildInfo.DiagnosticsSchemaVersion}");
        builder.AppendLine($"  unityApplicationVersion: {StringTheoryBuildInfo.UnityApplicationVersion}");
        builder.AppendLine($"  unityVersionMatchesBuildInfo: {StringTheoryBuildInfo.UnityVersionMatchesBuildInfo}");

        builder.AppendLine("GameState");
        builder.AppendLine($"  isRunning: {isRunning}");
        builder.AppendLine($"  isPaused: {isPaused}");
        builder.AppendLine($"  showMainMenu: {showMainMenu}");
        builder.AppendLine($"  mainMenuFlowActive: {mainMenuFlowActive}");
        builder.AppendLine($"  showMiniGames: {showMiniGames}");
        builder.AppendLine($"  showStartMenu: {showStartMenu}");
        builder.AppendLine($"  showToneLab: {showToneLab}");
        builder.AppendLine($"  showTuner: {showTuner}");
        builder.AppendLine($"  songTimer: {songTimer:0.000}");
        builder.AppendLine($"  loadedNotes: {(chartNotes != null ? chartNotes.Count : 0)}");
        builder.AppendLine($"  forceStandardTuning: {forceStandardTuning}");
        builder.AppendLine($"  useSongToneMappings: {useSongToneMappings}");
        builder.AppendLine($"  selectedLibraryType: {selectedSongLibraryType}");
        builder.AppendLine($"  selectedTrackIndex: {selectedTrackListIndex}");
        builder.AppendLine($"  currentTuning: {StringTuningUtils.FormatTuningDisplayName(GetVisibleTunerTargetPitches())}");

        if (currentSongEntry != null)
        {
            builder.AppendLine("CurrentSong");
            builder.AppendLine($"  songId: {currentSongEntry.SongId}");
            builder.AppendLine($"  displayName: {currentSongEntry.DisplayName}");
            builder.AppendLine($"  artist: {currentSongEntry.Artist}");
            builder.AppendLine($"  libraryType: {currentSongEntry.LibraryType}");
            builder.AppendLine($"  durationSeconds: {currentSongEntry.DurationSeconds:0.###}");
            builder.AppendLine($"  notationKind: {currentSongEntry.PrimaryNotationKind}");
            builder.AppendLine($"  directory: {currentSongEntry.SongDirectory}");
            builder.AppendLine($"  notationPath: {currentSongEntry.PrimaryNotationPath}");
            builder.AppendLine($"  audioPath: {currentSongEntry.Mp3Path}");
            builder.AppendLine($"  metadataPath: {currentSongEntry.MetadataPath}");
        }

        builder.AppendLine("SharedAudioSettings");
        builder.AppendLine(sharedAudioSettings != null ? JsonUtility.ToJson(sharedAudioSettings, true) : "(null)");
        builder.AppendLine($"  selectedToneLabInputLabel: {GetSharedAudioSelectedInputLabel()}");
        builder.AppendLine($"  selectedToneLabOutputLabel: {GetSharedAudioSelectedOutputLabel()}");
        builder.AppendLine($"  selectedInputChannelMode: {GetSharedAudioInputChannelModeLabel()}");
        builder.AppendLine($"  settingsPath: {ExternalContentPaths.PersistentAudioSettingsPath}");
        builder.AppendLine($"  inputChoices: {FormatStringList(sharedAudioInputDeviceChoices)}");
        builder.AppendLine($"  outputChoices: {FormatStringList(sharedAudioOutputDeviceChoices)}");

        builder.AppendLine("NotesDetector");
        builder.AppendLine($"  backendMode: {notesDetectorBackendMode}");
        builder.AppendLine($"  autoLaunchExternal: {autoLaunchNotesDetector}");
        builder.AppendLine($"  selectedNativeInputDeviceIndex: {selectedNativeNotesDetectorInputDeviceIndex}");
        builder.AppendLine($"  selectedNativeInputLabel: {GetSelectedNativeNotesDetectorInputDeviceLabel()}");
        builder.AppendLine($"  status: {GetNotesDetectorStatusText()}");
        builder.AppendLine($"  routineStatus: {GetNotesDetectorRoutineStatusText()}");
        builder.AppendLine($"  inputDevices: {FormatStringList(BuildNotesDetectorInputDeviceSnapshot())}");
        if (nativeNotesDetectorBridge != null)
        {
            NativeDetectorRuntimeInfo runtimeInfo = nativeNotesDetectorBridge.RefreshRuntimeInfo();
            NativeDetectorDeviceListPayload devices = nativeNotesDetectorBridge.RefreshDevices(forcePortAudioRescan: false);
            builder.AppendLine("NativeDetectorRuntime");
            builder.AppendLine(runtimeInfo != null ? JsonUtility.ToJson(runtimeInfo, true) : "(null)");
            builder.AppendLine("NativeDetectorDevices");
            builder.AppendLine(devices != null ? JsonUtility.ToJson(devices, true) : "(null)");
        }

        builder.AppendLine("RuntimeSettings");
        AppendRuntimeSettingsSnapshot(builder);
        return builder.ToString().TrimEnd();
    }

    private void AppendRuntimeSettingsSnapshot(StringBuilder builder)
    {
        List<RuntimeSettingSectionSnapshot> sections = BuildRuntimeSettingsSnapshot();
        if (sections == null || sections.Count == 0)
        {
            builder.AppendLine("  (none)");
            return;
        }

        for (int sectionIndex = 0; sectionIndex < sections.Count; sectionIndex++)
        {
            RuntimeSettingSectionSnapshot section = sections[sectionIndex];
            builder.AppendLine($"  [{section?.title ?? "Untitled"}]");
            List<RuntimeSettingSnapshot> settings = section?.settings;
            if (settings == null || settings.Count == 0)
            {
                builder.AppendLine("    (empty)");
                continue;
            }

            for (int settingIndex = 0; settingIndex < settings.Count; settingIndex++)
            {
                RuntimeSettingSnapshot setting = settings[settingIndex];
                if (setting == null)
                    continue;

                builder.AppendLine($"    {setting.id}: {setting.value} ({setting.label})");
            }
        }
    }

    private static string FormatStringList(IReadOnlyList<string> values)
    {
        if (values == null || values.Count == 0)
            return "(none)";

        return string.Join("; ", values);
    }

    private void Update()
    {
        if (!string.Equals(sharedAudioRefreshActionLabel, "REFRESH", StringComparison.Ordinal) &&
            sharedAudioRefreshActionResetAt > 0f &&
            Time.unscaledTime >= sharedAudioRefreshActionResetAt)
        {
            sharedAudioRefreshActionLabel = "REFRESH";
            sharedAudioRefreshActionResetAt = -1f;
            runtimeSettingsSnapshotDirty = true;
        }

        HandleNeonHorizonThemeShortcut();
        HandleBackgroundSecretShortcuts();

        bool shouldLogLoopCountdownFrame = Application.isEditor && loopRestartPauseRemainingSeconds > 0.0001f;
        long frameStartTicks = 0L;
        long sectionStartTicks = 0L;
        double handlePauseControlsMs = 0d;
        double disableLoopModeMs = 0d;
        double countdownAdvanceMs = 0d;
        double transportAdvanceMs = 0d;
        double noteByNoteGateMs = 0d;
        double songEndMs = 0d;
        double playbackSpeedMs = 0d;
        double audioSyncMs = 0d;
        double trackReloadMs = 0d;
        double inputUpdateMs = 0d;
        double sessionScoreMs = 0d;
        double gameplayUpdateMs = 0d;
        double inputLevelMs = 0d;
        double hintSendMs = 0d;
        double ensureRendererMs = 0d;
        double snapshotBuildMs = 0d;
        double renderMs = 0d;
        double toneLabMs = 0d;
        double uiMs = 0d;
        GuitarGameplaySnapshot snapshot = null;
        if (shouldLogLoopCountdownFrame)
        {
            if (string.IsNullOrWhiteSpace(loopCountdownEditorLogPath))
                StartLoopCountdownEditorLogSession("countdown-frame");

            frameStartTicks = GetLoopCountdownTimestamp();
            sectionStartTicks = frameStartTicks;
        }

        HandlePauseControls();
        if (showTuner)
            guitarTunerService?.Update(Time.unscaledDeltaTime);
        if (shouldLogLoopCountdownFrame)
        {
            long afterHandlePauseControlsTicks = GetLoopCountdownTimestamp();
            handlePauseControlsMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterHandlePauseControlsTicks);
            sectionStartTicks = afterHandlePauseControlsTicks;
        }

        DisableUnsupportedLoopModeState();
        if (shouldLogLoopCountdownFrame)
        {
            long afterDisableLoopModeTicks = GetLoopCountdownTimestamp();
            disableLoopModeMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterDisableLoopModeTicks);
            sectionStartTicks = afterDisableLoopModeTicks;
        }

        bool loopPreviewActive = showLoopSettings && loopSettingsPreviewPlaying;
        bool offsetHelperPreviewActive = showOffsetHelper && offsetHelperAdjusting && offsetHelperPreviewPlaying;
        bool loopGapActive = loopRestartPauseRemainingSeconds > 0.0001f;
        bool miniGameActive = showMiniGames && miniGameManager != null && miniGameManager.IsAnyGameActive;
        float songTimeBeforeAdvance = songTimer;

        if (loopGapActive)
        {
            loopRestartPauseRemainingSeconds = Mathf.Max(0f, loopRestartPauseRemainingSeconds - Time.deltaTime);
            loopGapActive = loopRestartPauseRemainingSeconds > 0.0001f;
        }
        if (shouldLogLoopCountdownFrame)
        {
            long afterCountdownAdvanceTicks = GetLoopCountdownTimestamp();
            countdownAdvanceMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterCountdownAdvanceTicks);
            sectionStartTicks = afterCountdownAdvanceTicks;
        }

        if (!miniGameActive && (!isPaused || loopPreviewActive || offsetHelperPreviewActive) && !loopGapActive)
        {
            audioSongTimer += Time.deltaTime * GetPlaybackSpeedScale();
            songTimer += Time.deltaTime * GetPlaybackSpeedScale();
            if (showOffsetHelper)
                HandleOffsetHelperLoopPlayback();
            else
                HandleLoopPlayback();
            loopGapActive = loopRestartPauseRemainingSeconds > 0.0001f;
        }
        if (shouldLogLoopCountdownFrame)
        {
            long afterTransportAdvanceTicks = GetLoopCountdownTimestamp();
            transportAdvanceMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterTransportAdvanceTicks);
            sectionStartTicks = afterTransportAdvanceTicks;
        }

        if (!miniGameActive)
            ApplyNoteByNoteTransportGate(songTimeBeforeAdvance, loopPreviewActive, offsetHelperPreviewActive, loopGapActive);
        if (shouldLogLoopCountdownFrame)
        {
            long afterNoteByNoteGateTicks = GetLoopCountdownTimestamp();
            noteByNoteGateMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterNoteByNoteGateTicks);
            sectionStartTicks = afterNoteByNoteGateTicks;
        }

        UpdateSongEndState();
        if (shouldLogLoopCountdownFrame)
        {
            long afterSongEndTicks = GetLoopCountdownTimestamp();
            songEndMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterSongEndTicks);
            sectionStartTicks = afterSongEndTicks;
        }

        UpdateStemGenerationState();

        ApplyPlaybackSpeedToAudio();
        if (shouldLogLoopCountdownFrame)
        {
            long afterPlaybackSpeedTicks = GetLoopCountdownTimestamp();
            playbackSpeedMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterPlaybackSpeedTicks);
            sectionStartTicks = afterPlaybackSpeedTicks;
        }

        if (!loopGapActive)
            SyncAudioToSongTimer(playImmediately: ShouldPlaybackAudio(loopPreviewActive, offsetHelperPreviewActive, loopGapActive));
        if (shouldLogLoopCountdownFrame)
        {
            long afterAudioSyncTicks = GetLoopCountdownTimestamp();
            audioSyncMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterAudioSyncTicks);
            sectionStartTicks = afterAudioSyncTicks;
        }

        if (gameplayMode == GuitarGameplayMode.Guitar && midiTrackIndex != currentLoadedTrackIndex)
            LoadTestSong(preservePauseUiState: isPaused || showMainMenu || showSongSettings || showSongSelection || showTrackSelection || showGlobalSettings || showLoopPausePopup);
        UpdateToneLabSongTonePlaybackOverride();
        if (shouldLogLoopCountdownFrame)
        {
            long afterTrackReloadTicks = GetLoopCountdownTimestamp();
            trackReloadMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterTrackReloadTicks);
            sectionStartTicks = afterTrackReloadTicks;
        }

        if (showMiniGames)
        {
            StopArcadeMidiInput();
            if (!loopGapActive)
            {
                ParseDetectorState();
                RefreshDetectorBackendStatus();
            }
        }
        else if (gameplayMode == GuitarGameplayMode.Guitar)
        {
            StopArcadeMidiInput();
            if (!loopGapActive)
            {
                ParseDetectorState();
                RefreshDetectorBackendStatus();
            }
        }
        else if (multiplayerRhythmModeActive)
        {
            StopArcadeMidiInput();
            if (!loopGapActive)
                UpdateMultiplayerRhythmInputState();
        }
        else
        {
            if (!loopGapActive)
                UpdateArcadeInputState();
        }
        if (shouldLogLoopCountdownFrame)
        {
            long afterInputUpdateTicks = GetLoopCountdownTimestamp();
            inputUpdateMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterInputUpdateTicks);
            sectionStartTicks = afterInputUpdateTicks;
        }

        if (showMiniGames && miniGameManager != null && miniGameManager.IsAnyGameActive && !isPaused && !loopGapActive)
        {
            miniGameManager.Update(Time.unscaledDeltaTime, BuildLatestDetectorCombinedPitches());
            if (miniGameManager.DetectorHintDirty)
            {
                MarkDetectorHintDirty();
                miniGameManager.ClearDetectorHintDirty();
            }
        }

        if (isPaused)
            UpdateSessionScoreState();
        if (shouldLogLoopCountdownFrame)
        {
            long afterSessionScoreTicks = GetLoopCountdownTimestamp();
            sessionScoreMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterSessionScoreTicks);
            sectionStartTicks = afterSessionScoreTicks;
        }

        if (!isPaused && !loopGapActive && !showMiniGames)
        {
            if (gameplayMode == GuitarGameplayMode.Guitar)
            {
                PruneHistory();
                UpdateGameplayStates();
                UpdateNoteByNoteWaitingStateAfterJudgment(loopPreviewActive, offsetHelperPreviewActive);
            }
            else
            {
                if (multiplayerRhythmModeActive)
                {
                    PruneMultiplayerRhythmInputHistory();
                    UpdateMultiplayerRhythmGameplayStates();
                }
                else
                {
                    PruneArcadeInputHistory();
                    UpdateArcadeGameplayStates();
                }
            }

            UpdateSessionScoreState();
            if (!multiplayerRhythmModeActive)
            {
                TryTriggerHeroModeGameOver();
                UpdateAndPersistSongBestScore();
            }
        }
        if (shouldLogLoopCountdownFrame)
        {
            long afterGameplayUpdateTicks = GetLoopCountdownTimestamp();
            gameplayUpdateMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterGameplayUpdateTicks);
            sectionStartTicks = afterGameplayUpdateTicks;
        }

        UpdateInputLevelEstimate();
        if (shouldLogLoopCountdownFrame)
        {
            long afterInputLevelTicks = GetLoopCountdownTimestamp();
            inputLevelMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterInputLevelTicks);
            sectionStartTicks = afterInputLevelTicks;
        }

        if ((gameplayMode == GuitarGameplayMode.Guitar || showMiniGames) && !loopGapActive)
            SendDetectorHintPacketIfNeeded();
        if (shouldLogLoopCountdownFrame)
        {
            long afterHintSendTicks = GetLoopCountdownTimestamp();
            hintSendMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterHintSendTicks);
            sectionStartTicks = afterHintSendTicks;
        }

        EnsureRenderer();
        if (shouldLogLoopCountdownFrame)
        {
            long afterEnsureRendererTicks = GetLoopCountdownTimestamp();
            ensureRendererMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterEnsureRendererTicks);
            sectionStartTicks = afterEnsureRendererTicks;
        }

        if (activeRenderer != null)
        {
            if (shouldLogLoopCountdownFrame)
            {
                long snapshotStartTicks = sectionStartTicks;
                snapshot = BuildSnapshot();
                long afterSnapshotTicks = GetLoopCountdownTimestamp();
                snapshotBuildMs = GetLoopCountdownElapsedMilliseconds(snapshotStartTicks, afterSnapshotTicks);
                activeRenderer.Render(snapshot);
                long afterRenderTicks = GetLoopCountdownTimestamp();
                renderMs = GetLoopCountdownElapsedMilliseconds(afterSnapshotTicks, afterRenderTicks);
                sectionStartTicks = afterRenderTicks;
            }
            else
            {
                activeRenderer.Render(BuildSnapshot());
            }
        }

        if (unityToneLabOverlay != null)
        {
            unityToneLabOverlay.SetVisible(showToneLab);
            if (showToneLab)
                unityToneLabOverlay.RefreshUi(syncControls: false);
        }
        if (guitarTunerOverlay != null)
            guitarTunerOverlay.SetVisible(showTuner);
        if (shouldLogLoopCountdownFrame)
        {
            long afterToneLabTicks = GetLoopCountdownTimestamp();
            toneLabMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterToneLabTicks);
            sectionStartTicks = afterToneLabTicks;
        }

        UpdateUiText();
        if (shouldLogLoopCountdownFrame)
        {
            long afterUiTicks = GetLoopCountdownTimestamp();
            uiMs = GetLoopCountdownElapsedMilliseconds(sectionStartTicks, afterUiTicks);
            double totalMs = GetLoopCountdownElapsedMilliseconds(frameStartTicks, afterUiTicks);
            int noteStateCount = noteStates != null ? noteStates.Count : 0;
            int arcadeNoteStateCount = arcadeNoteStates != null ? arcadeNoteStates.Count : 0;
            string rendererName = activeRenderer != null ? activeRenderer.GetType().Name : "null";
            LogLoopCountdownEditor(
                $"FRAME {loopCountdownEditorLogFrameIndex++} remaining={loopRestartPauseRemainingSeconds.ToString("F3", CultureInfo.InvariantCulture)} " +
                $"song={songTimer.ToString("F3", CultureInfo.InvariantCulture)} audio={audioSongTimer.ToString("F3", CultureInfo.InvariantCulture)} " +
                $"loop=[{loopStartTime.ToString("F3", CultureInfo.InvariantCulture)},{loopEndTime.ToString("F3", CultureInfo.InvariantCulture)}] " +
                $"paused={isPaused} nbmWait={noteByNoteWaitingForMatch} renderer={rendererName} renderMode={renderMode} gameplayMode={gameplayMode} " +
                $"notes={noteStateCount} arcadeNotes={arcadeNoteStateCount} " +
                $"timingsMs pause={handlePauseControlsMs:F3} disable={disableLoopModeMs:F3} countdown={countdownAdvanceMs:F3} advance={transportAdvanceMs:F3} " +
                $"gate={noteByNoteGateMs:F3} songEnd={songEndMs:F3} speed={playbackSpeedMs:F3} audioSync={audioSyncMs:F3} trackReload={trackReloadMs:F3} " +
                $"input={inputUpdateMs:F3} score={sessionScoreMs:F3} gameplay={gameplayUpdateMs:F3} inputLevel={inputLevelMs:F3} hint={hintSendMs:F3} " +
                $"ensureRenderer={ensureRendererMs:F3} snapshot={snapshotBuildMs:F3} render={renderMs:F3} toneLab={toneLabMs:F3} ui={uiMs:F3} total={totalMs:F3}");
        }

        if (Application.isEditor)
        {
            if (loopGapActive)
            {
                if (string.IsNullOrWhiteSpace(loopCountdownEditorLogPath))
                    StartLoopCountdownEditorLogSession("countdown-active");
            }
            else if (!string.IsNullOrWhiteSpace(loopCountdownEditorLogPath))
            {
                StopLoopCountdownEditorLogSession("countdown-finished");
            }
        }
    }

    private void HandlePauseControls()
    {
        if (showDiagnosticsConsentPopup)
        {
            HandleDiagnosticsConsentControls();
            return;
        }

        if (showBugReportScreen)
        {
            HandleBugReportControls();
            return;
        }

        if (showBugReportSentPopup)
        {
            HandleBugReportSentPopupControls();
            return;
        }

        if (showStartupTuningReminder)
        {
            if (IsUiSubmitPressed() ||
                IsUiBackPressed() ||
                IsUiPausePressed() ||
                IsStartupTuningReminderHeldDismissPressed())
            {
                DismissStartupTuningReminderFromUi();
            }

            return;
        }

        if (showLoopPausePopup)
        {
            HandleLoopPausePopupControls();
            return;
        }

        if (showArrangementDifficultyPopup)
        {
            HandleArrangementDifficultyPopupControls();
            return;
        }

        if (showHeroModeSettings)
        {
            HandleHeroModeSettingsControls();
            return;
        }

        if (showGameplayAudioPopup)
        {
            HandleGameplayAudioPopupControls();
            return;
        }

        if (showTuner)
        {
            HandleTunerControls();
            return;
        }

        if (showToneLab)
        {
            HandleToneLabControls();
            return;
        }

        if (showCharacterSelection)
        {
            HandleCharacterSelectionControls();
            return;
        }

        if (showNotesDetectorTestMenu)
        {
            HandleNotesDetectorTestControls();
            return;
        }

        if (showMiniGames)
        {
            HandleMiniGamesControls();
            return;
        }

        if (showGameModes)
        {
            HandleGameModesControls();
            return;
        }

        if (showOffsetHelper)
        {
            HandleOffsetHelperControls();
            return;
        }

        if (showLoopSettings)
        {
            HandleLoopSettingsControls();
            return;
        }

        if (Input.GetKeyDown(GameplayAudioPopupKey) &&
            !showSongSelection &&
            !showTrackSelection &&
            !showMainMenu &&
            !showStartMenu &&
            !showMultiplayerRhythmSetup &&
            !showCharacterSelection)
        {
            OpenGameplayAudioPopupFromUi();
            return;
        }

        if (Input.GetKeyDown(KeyCode.S) && renderMode.UsesTabHudLayout() && (isPaused || showSongSettings))
        {
            showSongSettings = !showSongSettings;
            if (showSongSettings)
                selectedSongSettingsIndex = 0;
            showGlobalSettings = false;
            showGameplayAudioPopup = false;
            gameplayAudioPopupOpenedWhilePaused = false;
            showGlobalSettingsSelectionPopup = false;
            globalSettingsSelectionPopupMode = GlobalSettingsSelectionPopupMode.None;
        }

        if (Input.GetKeyDown(KeyCode.G) && renderMode.UsesTabHudLayout() && (isPaused || showGlobalSettings))
        {
            showGlobalSettings = !showGlobalSettings;
            if (showGlobalSettings)
            {
                globalSettingsTransparentBackground = false;
                showBackgroundMoodSetter = false;
            }
            else
                CloseGlobalSettingsSelectionPopupFromUi();
            gameplayHudPreviewInMenus = false;
            showSongSettings = false;
            showGameplayAudioPopup = false;
        }

        if (!showGlobalSettings)
            CancelArcadeBindingCapture();

        if (showMultiplayerRhythmSetup)
        {
            HandleMultiplayerRhythmSetupControls();
            return;
        }

        if (showStartMenu)
        {
            HandleStartMenuControls();
            return;
        }

        if (showMainMenu)
        {
            HandleMainMenuControls();
            return;
        }

        if (showTrackSelection)
        {
            HandleTrackSelectionControls();
            return;
        }

        if (showSongSelection)
        {
            HandleSongSelectionControls();
            return;
        }

        if (showSongSettings)
        {
            HandleSongSettingsControls();
            return;
        }

        if (showBackgroundMoodSetter)
        {
            HandleBackgroundMoodSetterControls();
            return;
        }

        if (showGlobalSettings)
        {
            HandleGlobalSettingsControls();
            return;
        }

        if (songHasEnded)
        {
            isPaused = true;
            HandleSongEndControls();
            return;
        }

        if (IsRestartPressed())
        {
            if (notesDetectorGameplayTestActive)
                return;

            RetrySongFromUi();
            return;
        }

        if (!isPaused && Input.GetKeyDown(KeyCode.T))
        {
            OpenToneLabFromUi();
            return;
        }

        if (!isPaused && Input.GetKeyDown(KeyCode.L) && IsLoopModeAvailable())
        {
            ToggleLoopFromUi();
            return;
        }

        if (Input.GetKeyDown(BackgroundMoodSetterKey) && CanOpenBackgroundMoodSetter())
        {
            OpenBackgroundMoodSetterFromUi();
            return;
        }

        if (IsUiPausePressed())
        {
            isPaused = !isPaused;
            if (isPaused)
                selectedPauseActionIndex = GetFirstVisiblePauseActionIndex();
            gameplayHudPreviewInMenus = false;
            showSongSettings = false;
            showMainMenu = false;
            mainMenuFlowActive = false;
            showSongSelection = false;
            showTrackSelection = false;
            showGlobalSettings = false;
            showBackgroundMoodSetter = false;
            showGameplayAudioPopup = false;
            gameplayAudioPopupOpenedWhilePaused = false;
            CloseGlobalSettingsSelectionPopupFromUi();
            SyncAudioToSongTimer(playImmediately: !isPaused);
            return;
        }

        if (!isPaused)
            return;

        if (IsUiBackPressed())
        {
            ResumePlaybackFromUi();
            return;
        }

        if (notesDetectorGameplayTestActive)
        {
            if (IsUiUpPressed())
            {
                MovePauseActionSelectionFromUi(-1);
                return;
            }

            if (IsUiDownPressed())
            {
                MovePauseActionSelectionFromUi(1);
                return;
            }

            if (IsUiSubmitPressed())
            {
                ActivateSelectedPauseActionFromUi();
                return;
            }

            return;
        }

        if (Input.GetKeyDown(KeyCode.M))
        {
            SetPauseActionSelectionFromUi(7);
            OpenMainMenuFromUi();
            return;
        }

        if (Input.GetKeyDown(KeyCode.L))
        {
            SetPauseActionSelectionFromUi(4);
            OpenLibraryFromPauseFromUi();
            return;
        }

        if (Input.GetKeyDown(KeyCode.T))
        {
            SetPauseActionSelectionFromUi(6);
            OpenToneLabFromUi();
            return;
        }

        if (IsUiUpPressed())
        {
            MovePauseActionSelectionFromUi(-1);
            return;
        }

        if (IsUiDownPressed())
        {
            MovePauseActionSelectionFromUi(1);
            return;
        }

        if (IsUiSubmitPressed())
        {
            ActivateSelectedPauseActionFromUi();
            return;
        }

        if (HandleRightStickSeekInput(snapIntoLoopWindow: true))
            return;

        if (selectedPauseActionIndex == 0)
        {
            int horizontalDirection = GetHeldHorizontalArrowDirection();
            if (ConsumeHeldHorizontalUiStep("pause-speed", horizontalDirection))
            {
                AdjustPauseSpeedFromUi(horizontalDirection * 5);
                return;
            }

            return;
        }

        ConsumeHeldHorizontalUiStep("pause-speed", 0);

        if (selectedPauseActionIndex == 3)
        {
            ConsumeHeldHorizontalUiStep("pause-audio-mode", GetHeldHorizontalArrowDirection());
            return;
        }

        ConsumeHeldHorizontalUiStep("pause-audio-mode", 0);

        if (HandleGameplayHudPreviewToggleInput())
            return;


        if (IsLoopModeAvailable())
        {
            if (Input.GetKeyDown(KeyCode.Alpha1) || Input.GetKeyDown(KeyCode.Keypad1))
            {
                if (loopStartConfigured)
                {
                    selectedLoopMarker = 1;
                    SeekSongTimeFromUserNavigation(loopStartTime, false);
                }
            }
            else if (Input.GetKeyDown(KeyCode.Alpha2) || Input.GetKeyDown(KeyCode.Keypad2))
            {
                if (loopEndConfigured)
                {
                    selectedLoopMarker = 2;
                    SeekSongTimeFromUserNavigation(loopEndTime, false);
                }
            }
        }

        if (IsUiLeftPressed())
        {
            if (Time.unscaledTime - lastLeftArrowTapTime <= ArrowDoubleTapThreshold)
            {
                JumpToAdjacentNote(false);
                lastLeftArrowTapTime = -10f;
                return;
            }
            lastLeftArrowTapTime = Time.unscaledTime;
        }

        if (IsUiRightPressed())
        {
            if (Time.unscaledTime - lastRightArrowTapTime <= ArrowDoubleTapThreshold)
            {
                JumpToAdjacentNote(true);
                lastRightArrowTapTime = -10f;
                return;
            }
            lastRightArrowTapTime = Time.unscaledTime;
        }

        float seekDirection = 0f;
        if (IsUiLeftHeld())
            seekDirection -= 1f;
        if (IsUiRightHeld())
            seekDirection += 1f;

        if (Mathf.Approximately(seekDirection, 0f))
            return;

        SeekSongTimeFromUserNavigation(songTimer + (seekDirection * pauseSeekStepSeconds * Time.deltaTime), false);
        SnapSongTimeIntoLoopWindowIfNeeded();
    }

    private void HandleLoopSettingsControls()
    {
        if (UsesRhythmPracticeSectionLoop())
        {
            HandleRhythmPracticeLoopSettingsControls();
            return;
        }

        if (loopBookmarkRenameActive)
        {
            bool cancelRenamePressed =
                Input.GetKeyDown(KeyCode.Escape) ||
                TryGetButtonDown("Cancel") ||
                Input.GetKeyDown(KeyCode.JoystickButton1) ||
                Input.GetKeyDown(KeyCode.JoystickButton2);
            if (cancelRenamePressed)
            {
                CancelLoopBookmarkRenameFromUi();
                return;
            }

            bool confirmRenamePressed =
                Input.GetKeyDown(KeyCode.Return) ||
                Input.GetKeyDown(KeyCode.KeypadEnter) ||
                TryGetButtonDown("Submit") ||
                Input.GetKeyDown(KeyCode.JoystickButton0) ||
                Input.GetKeyDown(KeyCode.JoystickButton7) ||
                Input.GetKeyDown(KeyCode.JoystickButton9);
            if (confirmRenamePressed)
            {
                ConfirmLoopBookmarkRenameFromUi();
                return;
            }

            return;
        }

        if (IsLoopBookmarksTogglePressed())
        {
            ToggleLoopBookmarksPanel();
            return;
        }

        if (IsUiPausePressed())
        {
            OpenLoopPausePopup();
            return;
        }

        if (IsPreviewTogglePressed())
        {
            ToggleLoopSettingsPreviewPlayback();
            return;
        }

        if (Input.GetKeyDown(KeyCode.Alpha1) || Input.GetKeyDown(KeyCode.Keypad1))
        {
            TrySetLoopStartAtCurrentTime();
            return;
        }

        if (Input.GetKeyDown(KeyCode.Alpha2) || Input.GetKeyDown(KeyCode.Keypad2))
        {
            TrySetLoopEndAtCurrentTime();
            return;
        }

        if (IsUiUpPressed())
        {
            JumpToAdjacentTabSection(-1);
            return;
        }

        if (IsUiDownPressed())
        {
            JumpToAdjacentTabSection(1);
            return;
        }

        if (HandleRightStickSeekInput(snapIntoLoopWindow: false))
            return;

        float seekDirection = 0f;
        if (IsUiLeftHeld())
            seekDirection -= 1f;
        if (IsUiRightHeld())
            seekDirection += 1f;

        if (Mathf.Approximately(seekDirection, 0f))
            return;

        SeekSongTimeFromUserNavigation(songTimer + (seekDirection * pauseSeekStepSeconds * Time.deltaTime), false);
    }

    private void UpdateToneLabSongTonePlaybackOverride()
    {
        if (!useSongToneMappings ||
            showToneLab ||
            showMainMenu ||
            mainMenuFlowActive ||
            showSongSelection ||
            gameplayMode != GuitarGameplayMode.Guitar ||
            currentSongEntry == null ||
            currentSongEntry.PrimaryNotationKind != SongNotationSourceKind.ArrangementCache ||
            string.IsNullOrWhiteSpace(currentSongEntry.PrimaryNotationPath) ||
            songMetadata == null)
        {
            ResetToneLabSongTonePlaybackCache();
            ClearToneLabSongTonePlaybackOverride();
            return;
        }

        MusicXmlLoader.MusicXmlPartSummary activeSummary = GetResolvedActiveTrackSummary();
        string arrangementKey = GetArrangementGroupId(activeSummary);
        if (string.IsNullOrWhiteSpace(arrangementKey))
        {
            ResetToneLabSongTonePlaybackCache();
            ClearToneLabSongTonePlaybackOverride();
            return;
        }

        string songKey = BuildToneLabSongMappingSongKey(currentSongEntry);
        string toneName = string.Empty;
        string presetId = string.Empty;
        float toneTimeSeconds = IsSongStartTunerActive() ? 0f : audioSongTimer + (audioOffsetMs / 1000f);
        if (EnsureToneLabSongTonePlaybackCache(songKey, arrangementKey, activeSummary))
            ResolveCachedToneLabSongToneMapping(toneTimeSeconds, out toneName, out presetId);

        if (string.IsNullOrWhiteSpace(toneName))
        {
            ClearToneLabSongTonePlaybackOverride();
            return;
        }

        if (string.IsNullOrWhiteSpace(presetId))
        {
            ClearToneLabSongTonePlaybackOverride();
            return;
        }

        if (string.Equals(activeSongToneMappingSongKey, songKey, StringComparison.OrdinalIgnoreCase) &&
            string.Equals(activeSongToneMappingArrangementKey, arrangementKey, StringComparison.OrdinalIgnoreCase) &&
            string.Equals(activeSongToneMappingToneName, toneName, StringComparison.OrdinalIgnoreCase) &&
            string.Equals(activeSongToneMappingPresetId, presetId, StringComparison.Ordinal))
        {
            return;
        }

        EnsureToneLabRuntimeComponent();
        if (TryApplyToneLabPlaybackPresetOverride(presetId))
        {
            activeSongToneMappingSongKey = songKey;
            activeSongToneMappingArrangementKey = arrangementKey;
            activeSongToneMappingToneName = toneName;
            activeSongToneMappingPresetId = presetId;
        }
        else
        {
            ResetToneLabSongTonePlaybackCache();
            ClearToneLabSongTonePlaybackOverride();
        }
    }

