    {
        if (!showLoopSettings)
            return;

        if (UsesRhythmPracticeSectionLoop())
            ActivateArcadePracticeSectionFromUi(selectedArcadePracticeSectionIndex);
        else
            TrySetLoopStartAtCurrentTime();
    }

    public void SetLoopEndAtCurrentTimeFromUi()
    {
