    public void NudgeLoopTimelineFromUi(int direction)
    {
        if (!showLoopSettings || direction == 0)
            return;

        if (UsesRhythmPracticeSectionLoop())
        {
            MoveArcadePracticeSectionSelectionFromUi(direction);
            return;
