               renderMode.UsesHighway3D() &&
               !showMainMenu &&
               !mainMenuFlowActive &&
               !showStartMenu &&
               !showCharacterSelection &&
               !showSongSelection &&
               !showTrackSelection &&
               !showLibraryLoadingOverlay &&
