               !showMainMenu &&
               !showStartMenu &&
               !showCharacterSelection &&
               !showSongSelection &&
               !showTrackSelection &&
               !showLibraryLoadingOverlay &&
               !showGlobalSettingsSelectionPopup &&
               !showToneLab &&
