    public void OpenToneLabFromUi()
    {
        CancelDeferredSongSelectionOpen();
        EnsureToneLabRuntimeComponent();
        EnsureToneLabOverlayComponent();
        bool openingFromMainMenu = showMainMenu || mainMenuFlowActive;
        bool openingFromGameplay = !openingFromMainMenu && !isPaused && !songHasEnded;
        toneLabReturnContext = openingFromMainMenu
            ? ToneLabReturnContext.MainMenu
            : openingFromGameplay
                ? ToneLabReturnContext.Gameplay
                : ToneLabReturnContext.Pause;
        showToneLab = true;
        showTuner = false;
        tunerResumeGameplayAfterSkip = false;
        guitarTunerOverlay?.SetVisible(false);
        showNotesDetectorTestMenu = false;
        showMiniGames = false;
        showSongSettings = false;
        showSongSelection = false;
        songSelectionSongConfirmed = false;
        showTrackSelection = false;
        showGlobalSettings = false;
        showGameModes = false;
        showHeroModeSettings = false;
        showLoopSettings = false;
        showLoopPausePopup = false;
        showOffsetHelper = false;
        showStartupTuningReminder = false;
        resumeGameplayAfterStartupTuningReminder = false;
        showMainMenu = false;
        isPaused = true;
        SyncAudioToSongTimer(playImmediately: false);
        unityToneLabRuntime?.OpenForSession();
        unityToneLabOverlay?.SetVisible(true);
    }

    public void CloseToneLabFromUi()
    {
        showToneLab = false;
        HideToneLabUi();

        if (toneLabReturnContext == ToneLabReturnContext.MainMenu)
        {
            showMainMenu = true;
            mainMenuFlowActive = true;
            isPaused = true;
            SyncAudioToSongTimer(playImmediately: false);
        }
        else if (toneLabReturnContext == ToneLabReturnContext.Gameplay && !songHasEnded)
        {
            showMainMenu = false;
            mainMenuFlowActive = false;
            isPaused = false;
            SyncAudioToSongTimer(playImmediately: ShouldPlaybackAudio(false, false, false), forceSeek: noteByNoteWaitingForMatch);
        }
        else
        {
            showMainMenu = false;
            mainMenuFlowActive = false;
            isPaused = true;
            SyncAudioToSongTimer(playImmediately: false);
        }

        toneLabReturnContext = ToneLabReturnContext.Pause;
        RefreshToneLabSongTonePlaybackOverrideAfterExternalChange(applyIfEligible: true);
    }

    private void HideToneLabUi()
    {
        unityToneLabRuntime?.RestoreSelectedPresetWorkingRig();
        unityToneLabOverlay?.SetVisible(false);
    }

    private void EnsureToneLabComponents()
    {
        EnsureToneLabRuntimeComponent();
        EnsureToneLabOverlayComponent();
    }

    private void EnsureToneLabRuntimeComponent()
    {
        if (unityToneLabRuntime != null)
        {
            WireToneLabRuntimeCallbacks();
            return;
        }

        Transform existingRuntime = transform.Find("UnityToneLabRuntime");
        GameObject runtimeHost = existingRuntime != null ? existingRuntime.gameObject : new GameObject("UnityToneLabRuntime");
        runtimeHost.transform.SetParent(transform, false);
        unityToneLabRuntime = runtimeHost.GetComponent<UnityToneLabRuntime>();
        if (unityToneLabRuntime == null)
            unityToneLabRuntime = runtimeHost.AddComponent<UnityToneLabRuntime>();
        WireToneLabRuntimeCallbacks();
    }

    private void WireToneLabRuntimeCallbacks()
    {
        if (unityToneLabRuntime == null)
            return;

        unityToneLabRuntime.SharedInputRouteStarting = StartNativeDetectorFromToneLabSharedInput;
        unityToneLabRuntime.SharedInputRouteStopped = RestoreNativeDetectorIndependentInput;
        unityToneLabRuntime.SharedInputBlockReceived = SubmitToneLabSharedInputToNativeDetector;
        unityToneLabRuntime.RawInputBlockReceived = SubmitToneLabRawInputToTuner;
    }

    private void EnsureGuitarTunerService()
    {
        if (guitarTunerService == null)
            guitarTunerService = new GuitarTunerService();
    }

    private void EnsureGuitarTunerOverlayComponent()
    {
        EnsureGuitarTunerService();

        if (guitarTunerOverlay != null)
            return;

        Transform existingOverlay = transform.Find("GuitarTunerUI");
        GameObject overlayHost = existingOverlay != null ? existingOverlay.gameObject : new GameObject("GuitarTunerUI");
        overlayHost.transform.SetParent(transform, false);
        guitarTunerOverlay = overlayHost.GetComponent<GuitarTunerOverlay>();
        if (guitarTunerOverlay == null)
            guitarTunerOverlay = overlayHost.AddComponent<GuitarTunerOverlay>();
        guitarTunerOverlay.Initialize(this, guitarTunerService);
    }

    private void SubmitToneLabRawInputToTuner(float[] input, int inputChannels, int frameCount, int sampleRate, string inputChannelMode)
    {
        if (!showTuner || guitarTunerService == null)
            return;

        guitarTunerService.SubmitAudioBlock(input, inputChannels, frameCount, sampleRate, inputChannelMode);
    }

    private void EnsureToneLabOverlayComponent()
    {
        EnsureToneLabRuntimeComponent();

        if (unityToneLabOverlay != null)
            return;

        Transform existingOverlay = transform.Find("UnityToneLabUI");
        GameObject overlayHost = existingOverlay != null ? existingOverlay.gameObject : new GameObject("UnityToneLabUI");
        overlayHost.transform.SetParent(transform, false);
        unityToneLabOverlay = overlayHost.GetComponent<UnityToneLabOverlay>();
        if (unityToneLabOverlay == null)
            unityToneLabOverlay = overlayHost.AddComponent<UnityToneLabOverlay>();
        unityToneLabOverlay.Initialize(this, unityToneLabRuntime);
    }

