    public void ResumePlaybackFromUi()
    {
        bool restartLoopFromStartAfterResume = pendingLoopRestartFromStartAfterResume && loopEnabled && HasConfiguredLoopWindow();
        bool startWithLoopCountdown = pendingLoopStartCountdownAfterResume && loopEnabled && HasConfiguredLoopWindow();
        pendingLoopRestartFromStartAfterResume = false;
        pendingLoopStartCountdownAfterResume = false;
        loopPausePopupResumePlaybackOnConfirm = false;
        showToneLab = false;
        HideToneLabUi();
        gameplayHudPreviewInMenus = false;
        SetSongEndState(false);
        if ((showLoopSettings || showLoopPausePopup) && renderMode != loopSettingsReturnRenderMode)
            renderMode = loopSettingsReturnRenderMode;
        showLoopSettings = false;
        showLoopPausePopup = false;
        showArrangementDifficultyPopup = false;
        selectedLoopPausePopupIndex = 0;
        loopRestartPauseRemainingSeconds = 0f;
        loopSettingsPreviewPlaying = false;
        SnapSongTimeIntoLoopWindowIfNeeded();
        recentNoteEvents.Clear();
        latestDetectedPitches.Clear();
        latestEventNotesText = "--";
        latestNoteEventId = 0;
        latestPacketHadEvent = false;
        latestParsedInputLevel = -1f;
        Interlocked.Exchange(ref lastUdpPacketUtcTicks, 0L);
        ArmDetectorTimelineResetEventFloor(songTimer);
        MarkDetectorHintDirty();
        isPaused = false;
        showSongSettings = false;
        showMainMenu = false;
        mainMenuFlowActive = false;
        showSongSelection = false;
        songSelectionSongConfirmed = false;
        showTrackSelection = false;
        showGlobalSettings = false;
        showGameModes = false;
        showHeroModeSettings = false;
        loopSettingsOpenedFromGameModes = false;
        if (startWithLoopCountdown)
        {
            StartLoopRestartPause();
            return;
        }

        if (restartLoopFromStartAfterResume)
        {
            ResetSinglePlayerLoopRunState(loopStartTime);
            SeekSongTime(loopStartTime, false);
            return;
        }

        SyncAudioToSongTimer(playImmediately: ShouldPlaybackAudio(false, false, false), forceSeek: noteByNoteWaitingForMatch);
    }






private void OpenOrFocusToneLab()
{
#if UNITY_STANDALONE_WIN || UNITY_EDITOR_WIN
    const string toneLabWindowTitle = "Tone Lab";

    if (!ToneLabService.EnsureToneLabRuntimeFiles())
        return;

    string toneLabPath = ToneLabService.GetToneLabExecutablePath();
    string toneLabWorkingDirectory = Path.GetDirectoryName(toneLabPath);
    Debug.Log($"[ToneLab] Launch requested. Runtime executable path: {toneLabPath}");

    try
    {
        IntPtr existing = FindWindow(null, toneLabWindowTitle);
        if (existing != IntPtr.Zero)
        {
            ShowWindow(existing, SW_RESTORE);
            SetForegroundWindow(existing);
            CenterWindowOnUnityDisplay(existing);
            return;
        }

        if (!File.Exists(toneLabPath))
        {
            Debug.LogWarning($"Tone Lab executable not found at runtime path '{toneLabPath}'.");
            return;
        }

        if (TryStartToneLabProcess(toneLabPath, string.Empty, toneLabWorkingDirectory, false))
        {
            StartCoroutine(FocusToneLabWindowWhenReady(toneLabWindowTitle));
            return;
        }

        Debug.LogWarning("[ToneLab] Failed to launch Tone Lab executable.");
    }
    catch (Exception ex)
    {
        Debug.LogWarning($"Failed to launch Tone Lab: {ex}");
    }
#else
    if (!ToneLabService.EnsureToneLabRuntimeFiles())
        return;

    string toneLabPath = ToneLabService.GetToneLabExecutablePath();
    string toneLabWorkingDirectory = Path.GetDirectoryName(toneLabPath);
    try
    {
        if (StringTheoryPlatform.IsMacOS && Directory.Exists(ExternalContentPaths.PersistentToneLabAppBundlePath))
        {
            System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo
            {
                FileName = "open",
                Arguments = StringTheoryPlatform.QuoteArgument(ExternalContentPaths.PersistentToneLabAppBundlePath),
                UseShellExecute = false,
                CreateNoWindow = true
            });
            return;
        }

        if (!File.Exists(toneLabPath))
        {
            Debug.LogWarning($"Tone Lab executable not found at runtime path '{toneLabPath}'.");
            return;
        }

        StringTheoryPlatform.TryEnsureExecutable(toneLabPath);
        System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo
        {
            FileName = toneLabPath,
            WorkingDirectory = string.IsNullOrWhiteSpace(toneLabWorkingDirectory) ? null : toneLabWorkingDirectory,
            UseShellExecute = false,
            CreateNoWindow = false
        });
    }
    catch (Exception ex)
    {
        Debug.LogWarning($"Failed to launch Tone Lab: {ex}");
    }
#endif
}

#if UNITY_STANDALONE_WIN || UNITY_EDITOR_WIN
    private bool TryStartToneLabProcess(string fileName, string arguments, string workingDirectory, bool useShellExecute)
    {
        try
        {
            var startInfo = new System.Diagnostics.ProcessStartInfo
            {
                FileName = fileName,
                Arguments = arguments,
                WorkingDirectory = workingDirectory,
                UseShellExecute = useShellExecute,
                CreateNoWindow = false
            };

            System.Diagnostics.Process process = System.Diagnostics.Process.Start(startInfo);
            if (process != null)
            {
                Debug.Log($"[ToneLab] Launched using '{fileName} {arguments}' (UseShellExecute={useShellExecute}).");
                return true;
            }
        }
        catch (System.ComponentModel.Win32Exception ex) when (ex.NativeErrorCode == 1223)
        {
            Debug.LogWarning($"[ToneLab] Launch canceled by user/UAC for '{fileName}'. If ToneLab.exe requests admin privileges, remove that requirement from the executable manifest.");
        }
        catch (Exception ex)
        {
            Debug.LogWarning($"[ToneLab] Launch attempt failed: '{fileName} {arguments}'. {ex.Message}");
        }

        return false;
    }

    private System.Collections.IEnumerator FocusToneLabWindowWhenReady(string windowTitle)
    {
        const int attempts = 60;
        for (int i = 0; i < attempts; i++)
        {
            IntPtr window = FindWindow(null, windowTitle);
            if (window != IntPtr.Zero)
            {
                ShowWindow(window, SW_RESTORE);
                SetForegroundWindow(window);
                CenterWindowOnUnityDisplay(window);
                yield break;
            }

            yield return new WaitForSecondsRealtime(0.1f);
        }
    }

    private void CenterWindowOnUnityDisplay(IntPtr targetWindow)
    {
        if (targetWindow == IntPtr.Zero || Camera.main == null)
            return;

        IntPtr unityWindow = GetForegroundWindow();
        if (unityWindow == IntPtr.Zero)
            return;

        if (!GetWindowRect(unityWindow, out RECT unityRect) || !GetWindowRect(targetWindow, out RECT targetRect))
            return;

        int unityCenterX = unityRect.Left + ((unityRect.Right - unityRect.Left) / 2);
        int unityCenterY = unityRect.Top + ((unityRect.Bottom - unityRect.Top) / 2);
        int targetWidth = targetRect.Right - targetRect.Left;
        int targetHeight = targetRect.Bottom - targetRect.Top;

        int targetX = unityCenterX - (targetWidth / 2);
        int targetY = unityCenterY - (targetHeight / 2);

        SetWindowPos(targetWindow, IntPtr.Zero, targetX, targetY, 0, 0, SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE);
    }

    [System.Runtime.InteropServices.DllImport("user32.dll")]
    private static extern IntPtr FindWindow(string lpClassName, string lpWindowName);

    [System.Runtime.InteropServices.DllImport("user32.dll")]
    private static extern bool SetForegroundWindow(IntPtr hWnd);

    [System.Runtime.InteropServices.DllImport("user32.dll")]
    private static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);

    [System.Runtime.InteropServices.DllImport("user32.dll")]
    private static extern IntPtr GetForegroundWindow();

    [System.Runtime.InteropServices.DllImport("user32.dll")]
    private static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);

    [System.Runtime.InteropServices.DllImport("user32.dll")]
    private static extern bool SetWindowPos(IntPtr hWnd, IntPtr hWndInsertAfter, int X, int Y, int cx, int cy, uint uFlags);

    private const int SW_RESTORE = 9;
    private const uint SWP_NOSIZE = 0x0001;
    private const uint SWP_NOZORDER = 0x0004;
    private const uint SWP_NOACTIVATE = 0x0010;

    [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)]
    private struct RECT
    {
        public int Left;
        public int Top;
        public int Right;
        public int Bottom;
    }
#endif


    private string GetCurrentOffsetPartId()
    {
        if (useAutoTrackSelection)
        {
            if (currentSongPartSummaries.Count == 0)
                return string.Empty;

            MusicXmlLoader.MusicXmlPartSummary best = currentSongPartSummaries.OrderByDescending(s => s.Score).FirstOrDefault();
            return best != null ? (best.PartId ?? string.Empty) : string.Empty;
        }

        return selectedMusicXmlPartId ?? string.Empty;
    }

    private TrackOffsetOverride GetOrCreateTrackOffsetOverride(string partId)
    {
        if (songMetadata.trackOffsetOverrides == null)
            songMetadata.trackOffsetOverrides = new List<TrackOffsetOverride>();

        TrackOffsetOverride existing = songMetadata.trackOffsetOverrides.FirstOrDefault(o => string.Equals(o.partId ?? string.Empty, partId ?? string.Empty, StringComparison.OrdinalIgnoreCase));
        if (existing != null)
            return existing;

        TrackOffsetOverride created = new TrackOffsetOverride
        {
            partId = partId ?? string.Empty,
            useTrackOffset = false,
            offsetMs = globalAudioOffsetMs
        };

        songMetadata.trackOffsetOverrides.Add(created);
        return created;
    }

    private void RefreshEffectiveAudioOffset()
    {
        string partId = GetCurrentOffsetPartId();
        TrackOffsetOverride entry = null;

        if (!string.IsNullOrEmpty(partId) && songMetadata.trackOffsetOverrides != null)
            entry = songMetadata.trackOffsetOverrides.FirstOrDefault(o => string.Equals(o.partId ?? string.Empty, partId, StringComparison.OrdinalIgnoreCase));

        useTrackOffsetForCurrentTrack = entry != null && entry.useTrackOffset;
        audioOffsetMs = useTrackOffsetForCurrentTrack ? entry.offsetMs : globalAudioOffsetMs;
    }

    private void SetEffectiveOffsetForCurrentScope(float offsetMs)
    {
        if (useTrackOffsetForCurrentTrack)
        {
            string partId = GetCurrentOffsetPartId();
            TrackOffsetOverride entry = GetOrCreateTrackOffsetOverride(partId);
            entry.useTrackOffset = true;
            entry.offsetMs = offsetMs;
            audioOffsetMs = offsetMs;
            return;
        }

        globalAudioOffsetMs = offsetMs;
        audioOffsetMs = offsetMs;
    }

    private void ToggleOffsetScope()
    {
        string partId = GetCurrentOffsetPartId();
        if (string.IsNullOrEmpty(partId))
            return;

        TrackOffsetOverride entry = GetOrCreateTrackOffsetOverride(partId);
        entry.useTrackOffset = !entry.useTrackOffset;

        if (entry.useTrackOffset)
        {
            if (Mathf.Abs(entry.offsetMs) < 0.0001f)
                entry.offsetMs = globalAudioOffsetMs;
            useTrackOffsetForCurrentTrack = true;
            audioOffsetMs = entry.offsetMs;
        }
        else
        {
            useTrackOffsetForCurrentTrack = false;
            audioOffsetMs = globalAudioOffsetMs;
        }
    }





    private float GetPlaybackSpeedScale()
    {
        return Mathf.Clamp(playbackSpeedPercent / 100f, 0.01f, 2f);
    }

    private float GetVisualTabSpacingScale()
    {
        return Mathf.Clamp(tabSpeedOffsetPercent / 100f, 0.5f, 1.5f);
    }

    private void SeekSongTime(float targetTime, bool updateSelectedMarker)
    {
        SeekSongTimeInternal(
            targetTime,
            updateSelectedMarker,
            preserveResolvedProgressOnRewind: false,
            clearLoopRestartPause: true,
            syncAudioAfterSeek: true,
            playImmediatelyAfterSeek: !isPaused || (showLoopSettings && loopSettingsPreviewPlaying));
    }

    private void SeekSongTimeFromUserNavigation(float targetTime, bool updateSelectedMarker)
    {
        SeekSongTimeInternal(
            targetTime,
            updateSelectedMarker,
            preserveResolvedProgressOnRewind: false,
            clearLoopRestartPause: true,
            syncAudioAfterSeek: true,
            playImmediatelyAfterSeek: !isPaused || (showLoopSettings && loopSettingsPreviewPlaying));
        RebuildSessionProgressAfterUserSeek();
    }

    public void RequestTimelineSeek(float targetTime)
    {
        if (showMainMenu || showStartMenu || showSongSelection || showTrackSelection || songHasEnded || showTuner)
            return;

        float duration = GetSongDurationSeconds();
        float clampedTime = duration > 0.001f ? Mathf.Clamp(targetTime, 0f, duration) : Mathf.Max(0f, targetTime);
        SeekSongTimeFromUserNavigation(clampedTime, false);
    }

    private void SeekSongTimeForLoopRestartPause(float targetTime)
    {
        SeekSongTimeInternal(
            targetTime,
            updateSelectedMarker: false,
            preserveResolvedProgressOnRewind: true,
            clearLoopRestartPause: false,
            syncAudioAfterSeek: false,
            playImmediatelyAfterSeek: false);
    }

    private void SeekSongTimeInternal(float targetTime, bool updateSelectedMarker, bool preserveResolvedProgressOnRewind, bool clearLoopRestartPause, bool syncAudioAfterSeek, bool playImmediatelyAfterSeek)
    {
        float previousTime = songTimer;
        float clampedTime = Mathf.Max(-songStartDelaySeconds, targetTime);
        if (clearLoopRestartPause)
            loopRestartPauseRemainingSeconds = 0f;
        ClearNoteByNoteWaitingState();
        songTimer = clampedTime;
        audioSongTimer = clampedTime;

        if (updateSelectedMarker)
            UpdateSelectedLoopMarker(clampedTime);

        bool isRewinding = clampedTime < previousTime;
        if (multiplayerRhythmModeActive)
        {
            ApplyMultiplayerRhythmSeekState(clampedTime, isRewinding, preserveResolvedProgressOnRewind);
        }
        else
        {
        if (isRewinding)
        {
            if (!preserveResolvedProgressOnRewind)
            {
                for (int i = 0; i < noteStates.Count; i++)
                {
                    GameplayNoteState noteState = noteStates[i];
                    if (noteState.data.time > songTimer)
                    {
                        noteState.result = GameplayNoteResult.Pending;
                        noteState.resolvedAt = -1f;
                        noteState.isJudgeable = false;
                    }
                }

                for (int i = 0; i < arcadeNoteStates.Count; i++)
                {
                    ArcadeNoteState noteState = arcadeNoteStates[i];
                    if (noteState.data.time > songTimer)
                    {
                        noteState.result = GameplayNoteResult.Pending;
                        noteState.resolvedAt = -1f;
                        noteState.isJudgeable = false;
                    }
                }
            }
        }
        else
        {
            for (int i = 0; i < noteStates.Count; i++)
            {
                GameplayNoteState noteState = noteStates[i];
                if (noteState.IsResolved)
                    continue;

                float latestJudgeTime = noteState.data.time + hitWindowLate + GetSustainLateGrace(noteState.data) + MissJudgmentSafetyDelay;
                if (clampedTime > latestJudgeTime + (noteState.data.stringIdx >= 4 ? highStringExtraLate : 0f))
                {
                    noteState.result = GameplayNoteResult.Missed;
                    noteState.resolvedAt = clampedTime;
                    noteState.isJudgeable = false;
                }
            }

            for (int i = 0; i < arcadeNoteStates.Count; i++)
            {
                ArcadeNoteState noteState = arcadeNoteStates[i];
                if (noteState.IsResolved)
                    continue;

                if (clampedTime > noteState.data.time + arcadeHitWindowLate)
                {
                    noteState.result = GameplayNoteResult.Missed;
                    noteState.resolvedAt = clampedTime;
                    noteState.isJudgeable = false;
                }
            }
        }
        }

        recentNoteEvents.Clear();
        arcadeRecentInputEvents.Clear();
        activeArcadeSustains.Clear();
        latestArcadeInputEventId = 0;
        ResetArcadeCombo();
        if (multiplayerRhythmModeActive)
            ClearMultiplayerRhythmSeekTransientState();
        latestDetectedPitches.Clear();
        latestEventNotesText = "--";
        latestNoteEventId = 0;
        latestPacketHadEvent = false;
        Interlocked.Exchange(ref lastUdpPacketUtcTicks, 0L);
        ArmDetectorTimelineResetEventFloor(clampedTime);
        MarkDetectorHintDirty();
        if (syncAudioAfterSeek)
            SyncAudioToSongTimer(playImmediately: playImmediatelyAfterSeek);
        UpdateSongEndState();
    }

    private void RebuildSessionProgressAfterUserSeek()
    {
        if (multiplayerRhythmModeActive)
        {
            RebuildMultiplayerRhythmSessionProgressFromResolvedStates();
            return;
        }

        if (gameplayMode == GuitarGameplayMode.Arcade)
        {
            RebuildArcadeSessionProgressFromResolvedStates();
            return;
        }

        RebuildGuitarSessionProgressFromResolvedStates();
    }

    private void RebuildGuitarSessionProgressFromResolvedStates()
    {
        sessionScoredNoteIds.Clear();
        sessionScoreHits = 0;
        sessionScoreMisses = 0;
        currentSessionScoreValue = 0;
        currentSessionScorePercent = 0f;
        guitarComboCount = 0;

        if (noteStates == null || noteStates.Count == 0)
            return;

        Dictionary<int, int> eventNoteCounts = new Dictionary<int, int>();
        Dictionary<int, float> eventTimes = new Dictionary<int, float>();
        Dictionary<int, bool> eventHasPending = new Dictionary<int, bool>();
        Dictionary<int, bool> eventHasMiss = new Dictionary<int, bool>();
        Dictionary<int, bool> eventHasHit = new Dictionary<int, bool>();

        for (int i = 0; i < noteStates.Count; i++)
        {
            GameplayNoteState noteState = noteStates[i];
            if (noteState == null)
                continue;

            int eventKey = GetGuitarScoreEventKey(noteState.data, i);
            eventNoteCounts[eventKey] = eventNoteCounts.TryGetValue(eventKey, out int existingCount) ? existingCount + 1 : 1;
            if (!eventTimes.ContainsKey(eventKey))
                eventTimes[eventKey] = noteState.data.time;

            if (!noteState.IsResolved)
            {
                eventHasPending[eventKey] = true;
                continue;
            }

            if (noteState.IsHit)
                eventHasHit[eventKey] = true;
            else if (noteState.IsMissed)
                eventHasMiss[eventKey] = true;
        }

        int comboCount = 0;
        List<int> orderedEventKeys = eventTimes
            .OrderBy(pair => pair.Value)
            .ThenBy(pair => pair.Key)
            .Select(pair => pair.Key)
            .ToList();

        for (int i = 0; i < orderedEventKeys.Count; i++)
        {
            int eventKey = orderedEventKeys[i];
            if (eventHasPending.ContainsKey(eventKey))
                continue;

            sessionScoredNoteIds.Add(eventKey);
            if (eventHasMiss.ContainsKey(eventKey))
            {
                sessionScoreMisses++;
                comboCount = 0;
                continue;
            }

            if (eventHasHit.ContainsKey(eventKey))
                sessionScoreHits++;

            int noteCount = eventNoteCounts.TryGetValue(eventKey, out int countedNotes) ? Mathf.Max(1, countedNotes) : 1;
            currentSessionScoreValue += noteCount * 50 * GetGuitarScoreMultiplier(comboCount);
            comboCount++;
        }

        int total = eventTimes.Count;
        currentSessionScorePercent = total > 0
            ? Mathf.Clamp(100f * sessionScoreHits / total, 0f, 100f)
            : 0f;
        guitarComboCount = comboCount;
    }

    private void RebuildArcadeSessionProgressFromResolvedStates()
    {
        arcadeSessionScoredNoteIds.Clear();
        sessionScoreHits = 0;
        sessionScoreMisses = 0;
        currentSessionScorePercent = 0f;
        currentSessionArcadeScoreValue = 0;
        activeArcadeSustains.Clear();
        ResetArcadeCombo();

        if (arcadeNoteStates == null || arcadeNoteStates.Count == 0)
            return;

        List<ArcadeNoteState> orderedStates = arcadeNoteStates
            .Where(state => state != null)
            .OrderBy(state => state.data.time)
            .ThenBy(state => GetArcadeConsumeChordId(state.data))
            .ToList();

        int simulatedComboCount = 0;
        HashSet<int> processedChordIds = new HashSet<int>();
        for (int i = 0; i < orderedStates.Count; i++)
        {
            ArcadeNoteState noteState = orderedStates[i];
            if (!noteState.IsResolved)
                continue;

            int chordId = GetArcadeConsumeChordId(noteState.data);
            if (!processedChordIds.Add(chordId))
                continue;

            arcadeSessionScoredNoteIds.Add(chordId);
            if (noteState.IsHit)
            {
                sessionScoreHits++;
                currentSessionArcadeScoreValue += Mathf.Max(1, GetArcadeChordLaneCount(noteState.data)) * 50 * GetArcadeScoreMultiplier(simulatedComboCount);
                currentSessionArcadeScoreValue += GetAwardedArcadeSustainScore(chordId);
                simulatedComboCount++;
            }
            else if (noteState.IsMissed)
            {
                sessionScoreMisses++;
                simulatedComboCount = 0;
            }
        }

        int total = arcadeTotalChordCount > 0 ? arcadeTotalChordCount : CountArcadeChordGroups(arcadeNoteStates);
        currentSessionScorePercent = total > 0
            ? Mathf.Clamp(100f * sessionScoreHits / total, 0f, 100f)
            : 0f;
        arcadeComboCount = 0;
        arcadeComboActive = false;
    }

    private void ApplyMultiplayerRhythmSeekState(float clampedTime, bool isRewinding, bool preserveResolvedProgressOnRewind)
    {
        if (multiplayerRhythmPlayers == null)
            return;

        for (int playerIndex = 0; playerIndex < multiplayerRhythmPlayers.Length; playerIndex++)
        {
            MultiplayerRhythmPlayerState player = multiplayerRhythmPlayers[playerIndex];
            if (player == null || player.noteStates == null)
                continue;

            if (isRewinding)
            {
                if (preserveResolvedProgressOnRewind)
                    continue;

                for (int i = 0; i < player.noteStates.Count; i++)
                {
                    ArcadeNoteState noteState = player.noteStates[i];
                    if (noteState == null || noteState.data.time <= songTimer)
                        continue;

                    noteState.result = GameplayNoteResult.Pending;
                    noteState.resolvedAt = -1f;
                    noteState.isJudgeable = false;
                }

                continue;
            }

            for (int i = 0; i < player.noteStates.Count; i++)
            {
                ArcadeNoteState noteState = player.noteStates[i];
                if (noteState == null || noteState.IsResolved)
                    continue;

                if (clampedTime > noteState.data.time + arcadeHitWindowLate)
                {
                    noteState.result = GameplayNoteResult.Missed;
                    noteState.resolvedAt = clampedTime;
                    noteState.isJudgeable = false;
                }
            }
        }
    }

    private void ClearMultiplayerRhythmSeekTransientState()
    {
        if (multiplayerRhythmPlayers == null)
            return;

        for (int i = 0; i < multiplayerRhythmPlayers.Length; i++)
        {
            MultiplayerRhythmPlayerState player = multiplayerRhythmPlayers[i];
            if (player == null)
                continue;

            player.recentInputEvents.Clear();
            player.activeSustains.Clear();
            player.latestInputEventId = 0;
            player.inputNeedsUnpausedPrime = true;
            Array.Clear(player.heldLanes, 0, player.heldLanes.Length);
            Array.Clear(player.previousHeldLanes, 0, player.previousHeldLanes.Length);
            ResetMultiplayerRhythmCombo(player);
        }
    }

    private void RebuildMultiplayerRhythmSessionProgressFromResolvedStates()
    {
        if (multiplayerRhythmPlayers == null)
            return;

        int total = arcadeTotalChordCount > 0 ? arcadeTotalChordCount : 0;
        for (int playerIndex = 0; playerIndex < multiplayerRhythmPlayers.Length; playerIndex++)
        {
            MultiplayerRhythmPlayerState player = multiplayerRhythmPlayers[playerIndex];
            if (player == null)
                continue;

            player.sessionScoredChordIds.Clear();
            player.hitCount = 0;
            player.missCount = 0;
            player.scorePercent = 0f;
            player.scoreValue = 0;
            player.comboCount = 0;
            player.maxComboCount = 0;
            player.comboActive = false;
            player.activeSustains.Clear();

            if (player.noteStates == null || player.noteStates.Count == 0)
                continue;

            List<ArcadeNoteState> orderedStates = player.noteStates
                .Where(state => state != null)
                .OrderBy(state => state.data.time)
                .ThenBy(state => GetArcadeConsumeChordId(state.data))
                .ToList();

            int simulatedComboCount = 0;
            int maxCombo = 0;
            HashSet<int> processedChordIds = new HashSet<int>();
            for (int i = 0; i < orderedStates.Count; i++)
            {
                ArcadeNoteState noteState = orderedStates[i];
                if (!noteState.IsResolved)
                    continue;

                int chordId = GetArcadeConsumeChordId(noteState.data);
                if (!processedChordIds.Add(chordId))
                    continue;

                player.sessionScoredChordIds.Add(chordId);
                if (noteState.IsHit)
                {
                    player.hitCount++;
                    player.scoreValue += Mathf.Max(1, GetArcadeChordLaneCount(player.noteStates, noteState.data)) * 50 * GetArcadeScoreMultiplier(simulatedComboCount);
                    player.scoreValue += GetAwardedMultiplayerRhythmSustainScore(player, chordId);
                    simulatedComboCount++;
                    maxCombo = Mathf.Max(maxCombo, simulatedComboCount);
                }
                else if (noteState.IsMissed)
                {
                    player.missCount++;
                    simulatedComboCount = 0;
                }
            }

            player.comboCount = 0;
            player.maxComboCount = maxCombo;
            player.comboActive = false;
            player.scorePercent = total > 0
                ? Mathf.Clamp(100f * player.hitCount / total, 0f, 100f)
                : 0f;
        }

        UpdateMultiplayerRhythmWinnerState();
    }

    private void UpdateSelectedLoopMarker(float markerTime)
    {
        if (selectedLoopMarker == 1)
        {
            loopStartTime = Mathf.Max(0f, markerTime);
            loopStartConfigured = true;
            if (loopEndTime < loopStartTime + 0.05f)
            {
                loopEndTime = loopStartTime + 0.05f;
                loopEndConfigured = true;
            }
        }
        else if (selectedLoopMarker == 2)
        {
            loopEndTime = Mathf.Max(loopStartTime + 0.05f, markerTime);
            loopEndConfigured = true;
        }
    }

    private void OnApplicationQuit()
    {
        StopLoopCountdownEditorLogSession("application-quit");
        isRunning = false;
        if (receiveThread != null && receiveThread.IsAlive) receiveThread.Join(500);
        if (udpClient != null) udpClient.Close();
        CloseDetectorHintClient();
        StopArcadeMidiInput();
        ShutdownNativeNotesDetectorIfRunning();
        ShutdownNotesDetectorIfRunning();
        StringTheoryDiagnostics.Shutdown("application-quit");
    }

    private void OnDestroy()
    {
        StopLoopCountdownEditorLogSession("destroy");
        CloseDetectorHintClient();
        StopArcadeMidiInput();
        ShutdownNativeNotesDetectorIfRunning();
        ShutdownNotesDetectorIfRunning();
        ShutdownGeneratedSongPlayer();
    }

    private void OnDisable()
    {
        StopLoopCountdownEditorLogSession("disable");
        CloseDetectorHintClient();
        StopArcadeMidiInput();
        ShutdownNativeNotesDetectorIfRunning();
        ShutdownNotesDetectorIfRunning();
        ShutdownGeneratedSongPlayer();
    }

    private void TryLaunchNotesDetector(bool forceLaunch = false)
    {
        Debug.Log("[NotesDetector] TryLaunchNotesDetector() invoked.");

        if (notesDetectorBackendMode != NotesDetectorBackendMode.ExternalProcessUdp)
        {
            Debug.Log("[NotesDetector] Skipping external launch because native detector backend is selected.");
            return;
        }

        if (!forceLaunch && !autoLaunchNotesDetector)
        {
            Debug.Log("[NotesDetector] Auto-launch is disabled in inspector; skipping launch.");
            return;
        }

        if (notesDetectorProcess != null && !notesDetectorProcess.HasExited)
        {
            Debug.Log($"[NotesDetector] Process is already running (PID {notesDetectorProcess.Id}); skipping launch.");
            return;
        }

#if UNITY_STANDALONE_WIN || UNITY_EDITOR_WIN
        string detectorPath = Path.Combine(Application.streamingAssetsPath, notesDetectorRelativePath);
        Debug.Log($"[NotesDetector] Resolved executable path: {detectorPath}");

        if (!File.Exists(detectorPath))
        {
            Debug.LogWarning($"[NotesDetector] Executable not found at: {detectorPath}");
            return;
        }

        try
        {
            string detectorWorkingDirectory = Path.GetDirectoryName(detectorPath);
            Debug.Log($"[NotesDetector] Launching from working directory: {detectorWorkingDirectory}");

            System.Diagnostics.ProcessStartInfo startInfo;

#if UNITY_EDITOR_WIN
            if (openNotesDetectorConsoleWindowInEditor)
            {
                startInfo = new System.Diagnostics.ProcessStartInfo
                {
                    FileName = "cmd.exe",
                    Arguments = $"/k \"{detectorPath}\"",
                    WorkingDirectory = detectorWorkingDirectory,
                    UseShellExecute = true,
                    CreateNoWindow = false,
                };
                Debug.Log("[NotesDetector] Launch mode: cmd.exe /k (visible console window).");
            }
            else
#endif
            {
                startInfo = new System.Diagnostics.ProcessStartInfo
                {
                    FileName = detectorPath,
                    Arguments = string.Empty,
                    WorkingDirectory = detectorWorkingDirectory,
                    UseShellExecute = false,
                    CreateNoWindow = false,
                };
                Debug.Log("[NotesDetector] Launch mode: direct process start.");
            }

            notesDetectorProcess = System.Diagnostics.Process.Start(startInfo);
            if (notesDetectorProcess != null)
                Debug.Log($"[NotesDetector] Launched successfully (PID {notesDetectorProcess.Id}): {detectorPath}");
            else
                Debug.LogWarning("[NotesDetector] Process.Start returned null process handle.");
        }
        catch (Exception ex)
        {
            Debug.LogWarning($"[NotesDetector] Failed to launch '{detectorPath}': {ex}");
        }
#else
        Debug.Log($"[NotesDetector] Auto-launch is currently only enabled on Windows. Current platform: {Application.platform}");
#endif
    }

    private void ShutdownNotesDetectorIfRunning()
    {
        if (notesDetectorProcess == null)
            return;

        try
        {
            if (!notesDetectorProcess.HasExited)
                TryKillProcessTree(notesDetectorProcess);
        }
        catch (Exception ex)
        {
            Debug.LogWarning($"[NotesDetector] Failed to stop process cleanly: {ex.Message}");
        }
        finally
        {
            notesDetectorProcess.Dispose();
            notesDetectorProcess = null;
        }
    }

    private static void TryKillProcessTree(System.Diagnostics.Process process)
    {
        if (process == null)
            return;

        try
        {
            System.Reflection.MethodInfo killTreeMethod = typeof(System.Diagnostics.Process).GetMethod("Kill", new[] { typeof(bool) });
            if (killTreeMethod != null)
            {
                killTreeMethod.Invoke(process, new object[] { true });
                return;
            }
        }
        catch (Exception)
        {
            // Fall back to regular kill when process-tree termination is unavailable or unsupported.
        }

        process.Kill();
    }

    private void StartConfiguredNotesDetectorBackend()
    {
        if (notesDetectorBackendMode == NotesDetectorBackendMode.NativeEmbeddedBridge)
        {
            EnsureNativeNotesDetectorBridge();
            RefreshNativeNotesDetectorUiState();
            RefreshSelectedNativeDetectorInputDeviceFromSharedSettings(savePreference: true);
            UnityToneLabRuntime.SharedInputRouteInfo sharedRoute = unityToneLabRuntime?.GetActiveSharedInputRouteInfo();
            bool started = sharedRoute != null
                ? StartNativeDetectorFromToneLabSharedInput(sharedRoute)
                : nativeNotesDetectorBridge?.Start(selectedNativeNotesDetectorInputDeviceIndex, GetSharedAudioInputChannelModeLabel()) == true;
            RefreshNativeNotesDetectorUiState();
            Debug.Log($"[NativeNotesDetector] Configured start {(started ? "succeeded" : "failed")} on {selectedNativeNotesDetectorInputDeviceIndex}: {GetNotesDetectorStatusText()}");
            MarkDetectorHintDirty();
            return;
        }

        if (autoLaunchNotesDetector)
            TryLaunchNotesDetector();
    }

    private bool StartNativeDetectorFromToneLabSharedInput(UnityToneLabRuntime.SharedInputRouteInfo route)
    {
        if (route == null || notesDetectorBackendMode != NotesDetectorBackendMode.NativeEmbeddedBridge)
            return false;

        EnsureNativeNotesDetectorBridge();
        RefreshSelectedNativeDetectorInputDeviceFromSharedSettings(savePreference: true);
        if (nativeNotesDetectorBridge == null)
            return false;

        NativeDetectorSharedInputRoute nativeRoute = new NativeDetectorSharedInputRoute
        {
            inputDeviceIndex = route.InputDeviceIndex,
            inputDeviceDisplayName = route.InputDeviceDisplayName,
            hostApiName = route.HostApiName,
            sampleRate = route.SampleRate,
            inputChannelCount = route.InputChannelCount,
            maxBlockFrames = route.MaxBlockFrames,
            inputChannelMode = SharedAudioInputChannelModes.Normalize(route.InputChannelMode)
        };

        bool started = nativeNotesDetectorBridge.StartSharedInput(nativeRoute);
        RefreshNativeNotesDetectorUiState();
        Debug.Log($"[NativeNotesDetector] Shared Tone Lab input {(started ? "enabled" : "failed")} on {nativeRoute.inputDeviceIndex}: {GetNotesDetectorStatusText()}");
        MarkDetectorHintDirty();
        return started;
    }

    private void RestoreNativeDetectorIndependentInput()
    {
        if (notesDetectorBackendMode != NotesDetectorBackendMode.NativeEmbeddedBridge)
            return;

        EnsureNativeNotesDetectorBridge();
        RefreshSelectedNativeDetectorInputDeviceFromSharedSettings(savePreference: true);
        bool started = nativeNotesDetectorBridge?.Start(selectedNativeNotesDetectorInputDeviceIndex, GetSharedAudioInputChannelModeLabel()) == true;
        RefreshNativeNotesDetectorUiState();
        Debug.Log($"[NativeNotesDetector] Independent input restore {(started ? "succeeded" : "failed")} on {selectedNativeNotesDetectorInputDeviceIndex}: {GetNotesDetectorStatusText()}");
        MarkDetectorHintDirty();
    }

    private bool SubmitToneLabSharedInputToNativeDetector(float[] input, int inputChannels, int frameCount, int sampleRate, string inputChannelMode)
    {
        if (notesDetectorBackendMode != NotesDetectorBackendMode.NativeEmbeddedBridge || nativeNotesDetectorBridge == null)
            return false;

        return nativeNotesDetectorBridge.SubmitSharedInput(
            input,
            frameCount,
            inputChannels,
            sampleRate,
            SharedAudioInputChannelModes.Normalize(inputChannelMode));
    }

    private void EnsureNativeNotesDetectorBridge()
    {
        if (nativeNotesDetectorBridge != null)
        {
            if (Application.isEditor && !string.IsNullOrWhiteSpace(notesDetectorEditorLogPath))
                nativeNotesDetectorBridge.SetDebugLogPath(notesDetectorEditorLogPath);
            return;
        }

        nativeNotesDetectorBridge = new NativeNotesDetectorBridge();
        if (Application.isEditor && !string.IsNullOrWhiteSpace(notesDetectorEditorLogPath))
            nativeNotesDetectorBridge.Initialize();
        if (Application.isEditor && !string.IsNullOrWhiteSpace(notesDetectorEditorLogPath))
            nativeNotesDetectorBridge.SetDebugLogPath(notesDetectorEditorLogPath);
    }

    private void RefreshNativeNotesDetectorDeviceList(bool forcePortAudioRescan = false)
    {
        EnsureNativeNotesDetectorBridge();
        if (nativeNotesDetectorBridge == null)
            return;

        NativeDetectorDeviceListPayload payload = nativeNotesDetectorBridge.RefreshDevices(forcePortAudioRescan);
        nativeNotesDetectorInputDevices.Clear();

        if (payload?.devices == null)
            return;

        for (int i = 0; i < payload.devices.Length; i++)
        {
            NativeDetectorInputDevice device = payload.devices[i];
            if (device != null)
                nativeNotesDetectorInputDevices.Add(device);
        }
    }

    private void RefreshNativeNotesDetectorUiState(bool forcePortAudioRescan = false)
    {
        EnsureNativeNotesDetectorBridge();
        if (nativeNotesDetectorBridge == null)
            return;

        RefreshNativeNotesDetectorDeviceList(forcePortAudioRescan);
        nativeNotesDetectorBridge.RefreshNativeStatus();
        nativeNotesDetectorRuntimeInfo = nativeNotesDetectorBridge.RuntimeInfo ?? new NativeDetectorRuntimeInfo();
    }

    private void LoadSharedAudioSettingsFromDisk()
    {
        EnsureToneLabRuntimeComponent();
        sharedAudioSettings = SharedAudioSettingsUtility.Load(ExternalContentPaths.PersistentAudioSettingsPath) ?? new SharedAudioSettings();

        bool needsSave = false;
        if (!File.Exists(ExternalContentPaths.PersistentAudioSettingsPath))
            needsSave = true;

        if (sharedAudioSettings.advanced == null)
        {
            sharedAudioSettings.advanced = new SharedAudioAdvancedSettings();
            needsSave = true;
        }

        if (string.IsNullOrWhiteSpace(sharedAudioSettings.inputDeviceName))
        {
            string legacyToneInput = unityToneLabRuntime?.CurrentSettings?.input_device_name;
            if (!string.IsNullOrWhiteSpace(legacyToneInput))
            {
                sharedAudioSettings.inputDeviceName = NormalizeSharedAudioStoredSelection(legacyToneInput);
                needsSave = true;
            }
            else
            {
                int legacyDetectorIndex = PlayerPrefs.GetInt(NativeDetectorInputDevicePrefsKey, -1);
                if (legacyDetectorIndex >= 0)
                {
                    RefreshNativeNotesDetectorDeviceList();
                    sharedAudioSettings.inputDeviceName = NormalizeSharedAudioStoredSelection(ResolveNativeDetectorInputDeviceName(legacyDetectorIndex));
                    needsSave = true;
                }
            }
        }

        if (string.IsNullOrWhiteSpace(sharedAudioSettings.outputDeviceName))
        {
            string legacyToneOutput = unityToneLabRuntime?.CurrentSettings?.output_device_name;
            if (!string.IsNullOrWhiteSpace(legacyToneOutput))
            {
                sharedAudioSettings.outputDeviceName = NormalizeSharedAudioStoredSelection(legacyToneOutput);
                needsSave = true;
            }
        }

        int normalizedBuffer = NormalizeSharedMonitoringBufferSize(sharedAudioSettings.monitoringBufferSize);
        if (normalizedBuffer != sharedAudioSettings.monitoringBufferSize)
        {
            sharedAudioSettings.monitoringBufferSize = normalizedBuffer;
            needsSave = true;
        }

        float normalizedSongVolume = Mathf.Clamp(sharedAudioSettings.songVolumePercent, 0f, 100f);
        if (!Mathf.Approximately(sharedAudioSettings.songVolumePercent, normalizedSongVolume))
        {
            sharedAudioSettings.songVolumePercent = normalizedSongVolume;
            needsSave = true;
        }

        float normalizedGuitarVolume = Mathf.Clamp(sharedAudioSettings.guitarVolumePercent, 0f, UnityToneLabRuntime.MaxMonitorVolumePercent);
        if (!Mathf.Approximately(sharedAudioSettings.guitarVolumePercent, normalizedGuitarVolume))
        {
            sharedAudioSettings.guitarVolumePercent = normalizedGuitarVolume;
            needsSave = true;
        }

        string normalizedResamplerMode = SharedAudioDetectorResamplerModes.Normalize(sharedAudioSettings.detectorResamplerMode);
        if (!string.Equals(sharedAudioSettings.detectorResamplerMode, normalizedResamplerMode, StringComparison.Ordinal))
        {
            sharedAudioSettings.detectorResamplerMode = normalizedResamplerMode;
            needsSave = true;
        }

        SharedAudioAdvancedSettings normalizedAdvanced = NormalizeSharedAudioAdvancedSettings(sharedAudioSettings.advanced, normalizedBuffer, out bool advancedChanged);
        sharedAudioSettings.advanced = normalizedAdvanced;
        if (advancedChanged)
            needsSave = true;

        if (!string.IsNullOrWhiteSpace(sharedAudioSettings.inputDeviceName))
            sharedAudioSettings.inputDeviceName = NormalizeSharedAudioStoredSelection(sharedAudioSettings.inputDeviceName);
        if (!string.IsNullOrWhiteSpace(sharedAudioSettings.outputDeviceName))
            sharedAudioSettings.outputDeviceName = NormalizeSharedAudioStoredSelection(sharedAudioSettings.outputDeviceName);

        if (needsSave)
            SaveSharedAudioSettingsToDisk();
    }

    private void SaveSharedAudioSettingsToDisk()
    {
        if (sharedAudioSettings == null)
            sharedAudioSettings = new SharedAudioSettings();

        sharedAudioSettings.version = 8;
        sharedAudioSettings.inputDeviceName = NormalizeSharedAudioStoredSelection(sharedAudioSettings.inputDeviceName);
        sharedAudioSettings.outputDeviceName = NormalizeSharedAudioStoredSelection(sharedAudioSettings.outputDeviceName);
        sharedAudioSettings.monitoringBufferSize = NormalizeSharedMonitoringBufferSize(sharedAudioSettings.monitoringBufferSize);
        sharedAudioSettings.songVolumePercent = Mathf.Clamp(sharedAudioSettings.songVolumePercent, 0f, 100f);
        sharedAudioSettings.guitarVolumePercent = Mathf.Clamp(sharedAudioSettings.guitarVolumePercent, 0f, UnityToneLabRuntime.MaxMonitorVolumePercent);
        sharedAudioSettings.detectorResamplerMode = SharedAudioDetectorResamplerModes.Normalize(sharedAudioSettings.detectorResamplerMode);
        sharedAudioSettings.advanced = NormalizeSharedAudioAdvancedSettings(sharedAudioSettings.advanced, sharedAudioSettings.monitoringBufferSize, out _);
        SharedAudioSettingsUtility.Save(ExternalContentPaths.PersistentAudioSettingsPath, sharedAudioSettings);
    }

    private void RefreshSharedAudioRoutingCatalogs(bool refreshToneLabDevices, bool refreshDetectorDevices, bool forcePortAudioRescan = false)
    {
        EnsureToneLabRuntimeComponent();
        bool restartDetectorAfterForcedRescan = false;
        if (forcePortAudioRescan && refreshDetectorDevices)
        {
            EnsureNativeNotesDetectorBridge();
            restartDetectorAfterForcedRescan = nativeNotesDetectorBridge?.IsRunning() == true;
            nativeNotesDetectorBridge?.Shutdown(forceNativeShutdown: true);
        }

        if (refreshToneLabDevices)
            unityToneLabRuntime?.RefreshInputDevices(forcePortAudioRescan);
        if (refreshDetectorDevices)
        {
            RefreshNativeNotesDetectorUiState(forcePortAudioRescan: false);
            if (restartDetectorAfterForcedRescan && notesDetectorBackendMode == NotesDetectorBackendMode.NativeEmbeddedBridge)
            {
                RefreshSelectedNativeDetectorInputDeviceFromSharedSettings(savePreference: true);
                StartConfiguredNotesDetectorBackend();
            }
        }

        sharedAudioInputDeviceChoices.Clear();
        sharedAudioInputDeviceChoices.Add(SharedAudioAutomaticLabel);

        string[] toneInputs = unityToneLabRuntime?.InputDevices;
        if (toneInputs != null)
        {
            for (int i = 0; i < toneInputs.Length; i++)
                AddSharedAudioChoice(sharedAudioInputDeviceChoices, toneInputs[i]);
        }

        for (int i = 0; i < nativeNotesDetectorInputDevices.Count; i++)
            AddSharedAudioChoice(sharedAudioInputDeviceChoices, ResolveNativeDetectorInputDeviceDisplayLabel(nativeNotesDetectorInputDevices[i]));

        sharedAudioOutputDeviceChoices.Clear();
        sharedAudioOutputDeviceChoices.Add(SharedAudioAutomaticLabel);
        string[] toneOutputs = unityToneLabRuntime?.OutputDevices;
        if (toneOutputs != null)
        {
            for (int i = 0; i < toneOutputs.Length; i++)
                AddSharedAudioChoice(sharedAudioOutputDeviceChoices, toneOutputs[i]);
        }

        UpdateSharedAudioRuntimeSettingOptions();
    }

    private static void AddSharedAudioChoice(List<string> choices, string candidate)
    {
        if (choices == null || string.IsNullOrWhiteSpace(candidate))
            return;

        string normalizedCandidate = SharedAudioSettingsUtility.NormalizeDeviceKey(candidate);
        string physicalCandidate = SharedAudioSettingsUtility.NormalizePhysicalDeviceKey(candidate);
        if (string.IsNullOrWhiteSpace(normalizedCandidate))
            return;

        for (int i = 0; i < choices.Count; i++)
        {
            if (string.Equals(SharedAudioSettingsUtility.NormalizeDeviceKey(choices[i]), normalizedCandidate, StringComparison.Ordinal))
                return;
            if (!string.IsNullOrWhiteSpace(physicalCandidate) &&
                string.Equals(SharedAudioSettingsUtility.NormalizePhysicalDeviceKey(choices[i]), physicalCandidate, StringComparison.Ordinal))
            {
                return;
            }
        }

        choices.Add(candidate.Trim());
    }

    private void UpdateSharedAudioRuntimeSettingOptions()
    {
        UpdateRuntimeEnumOptions("audio.inputDevice", sharedAudioInputDeviceChoices);
        UpdateRuntimeEnumOptions("audio.inputChannelMode", SharedAudioInputChannelModes.Choices);
        UpdateRuntimeEnumOptions("audio.outputDevice", sharedAudioOutputDeviceChoices);
        UpdateRuntimeEnumOptions("audio.monitoringLatency", UnityToneLabRuntime.SharedMonitoringLatencyOptions);
    }

    private void UpdateRuntimeEnumOptions(string settingId, IReadOnlyList<string> options)
    {
        if (string.IsNullOrWhiteSpace(settingId) || !runtimeSettingById.TryGetValue(settingId, out RuntimeSettingDefinition definition))
            return;

        definition.EnumOptions = options != null ? new List<string>(options) : new List<string>();
        runtimeSettingsSnapshotDirty = true;
    }

    private static int NormalizeSharedMonitoringBufferSize(int bufferSize)
    {
        return UnityToneLabRuntime.ParseSharedMonitoringLatencyBufferSize(UnityToneLabRuntime.GetSharedMonitoringLatencyLabel(bufferSize));
    }

    private static string NormalizeSharedAudioStoredSelection(string value)
    {
        if (string.IsNullOrWhiteSpace(value))
            return string.Empty;

        string normalized = SharedAudioSettingsUtility.NormalizeStoredDeviceName(value);
        if (normalized.StartsWith("Automatic", StringComparison.OrdinalIgnoreCase) ||
            normalized.StartsWith("System Default", StringComparison.OrdinalIgnoreCase) ||
            normalized.StartsWith("No input", StringComparison.OrdinalIgnoreCase) ||
            normalized.StartsWith("No output", StringComparison.OrdinalIgnoreCase))
            return string.Empty;

        return normalized;
    }

    private static bool IsSharedAudioAutomaticValue(string value)
    {
        return string.IsNullOrWhiteSpace(value) || string.Equals(value, SharedAudioAutomaticLabel, StringComparison.OrdinalIgnoreCase);
    }

    private static string StripAdvancedAudioDeviceDecorations(string value)
    {
        string normalized = NormalizeSharedAudioStoredSelection(value);
        if (string.IsNullOrWhiteSpace(normalized))
            return string.Empty;

        int suffixIndex = normalized.LastIndexOf(" (#", StringComparison.Ordinal);
        if (suffixIndex >= 0 && normalized.EndsWith(")", StringComparison.Ordinal))
            normalized = normalized.Substring(0, suffixIndex);

        int hostIndex = normalized.LastIndexOf(" [", StringComparison.Ordinal);
        if (hostIndex >= 0 && normalized.EndsWith("]", StringComparison.Ordinal))
            normalized = normalized.Substring(0, hostIndex);

        return normalized.Trim();
    }

    private static string ResolveChoiceByNormalizedName(IReadOnlyList<string> choices, string candidate)
    {
        if (choices == null || choices.Count == 0 || string.IsNullOrWhiteSpace(candidate))
            return string.Empty;

        string normalizedCandidate = SharedAudioSettingsUtility.NormalizeDeviceKey(candidate);
        for (int i = 0; i < choices.Count; i++)
        {
            string choice = choices[i];
            if (string.Equals(SharedAudioSettingsUtility.NormalizeDeviceKey(choice), normalizedCandidate, StringComparison.Ordinal))
                return choice;
        }

        string physicalCandidate = SharedAudioSettingsUtility.NormalizePhysicalDeviceKey(candidate);
        if (!string.IsNullOrWhiteSpace(physicalCandidate))
        {
            for (int i = 0; i < choices.Count; i++)
            {
                string choice = choices[i];
                if (string.Equals(SharedAudioSettingsUtility.NormalizePhysicalDeviceKey(choice), physicalCandidate, StringComparison.Ordinal))
                    return choice;
            }
        }

        return string.Empty;
    }

    private string ResolveToneLabDisplayNameFromAdvancedSelection(string advancedSelection, IReadOnlyList<string> toneLabDevices)
    {
        return ResolveChoiceByNormalizedName(toneLabDevices, StripAdvancedAudioDeviceDecorations(advancedSelection));
    }

    private string ResolveAdvancedChoiceFromToneLabDisplayName(string toneLabDisplayName, bool input)
    {
        if (unityToneLabRuntime == null || sharedAudioSettings?.advanced == null)
            return string.Empty;

        string backendMode = SharedAudioBackendModes.NormalizeForCurrentPlatform(sharedAudioSettings.advanced.backendMode);
        if (string.Equals(backendMode, SharedAudioBackendModes.Auto, StringComparison.Ordinal))
            return string.Empty;

        IReadOnlyList<string> choices = input
            ? unityToneLabRuntime.GetAdvancedInputDeviceChoices(backendMode)
            : unityToneLabRuntime.GetAdvancedOutputDeviceChoices(backendMode);

        for (int i = 0; i < choices.Count; i++)
        {
            string choice = choices[i];
            if (string.Equals(choice, SharedAudioAutomaticLabel, StringComparison.OrdinalIgnoreCase))
                continue;

            if (!string.IsNullOrWhiteSpace(ResolveChoiceByNormalizedName(new[] { toneLabDisplayName }, StripAdvancedAudioDeviceDecorations(choice))))
                return choice;
        }

        return string.Empty;
    }

    private static SharedAudioAdvancedSettings NormalizeSharedAudioAdvancedSettings(SharedAudioAdvancedSettings source, int fallbackBufferSize, out bool changed)
    {
        SharedAudioAdvancedSettings normalized = SharedAudioSettingsUtility.CloneAdvancedSettings(source);
        changed = source == null;

        string normalizedInputChannelMode = SharedAudioInputChannelModes.Normalize(normalized.inputChannelMode);
        if (!string.Equals(normalized.inputChannelMode, normalizedInputChannelMode, StringComparison.Ordinal) ||
            (source != null && !string.Equals(source.inputChannelMode ?? string.Empty, normalizedInputChannelMode, StringComparison.Ordinal)))
        {
            normalized.inputChannelMode = normalizedInputChannelMode;
            changed = true;
        }

        if (!string.Equals(normalized.backendMode, SharedAudioBackendModes.NormalizeForCurrentPlatform(normalized.backendMode), StringComparison.Ordinal))
        {
            normalized.backendMode = SharedAudioBackendModes.NormalizeForCurrentPlatform(normalized.backendMode);
            changed = true;
        }

        string normalizedInput = NormalizeSharedAudioStoredSelection(normalized.inputDeviceName);
        if (!string.Equals(normalized.inputDeviceName, normalizedInput, StringComparison.Ordinal))
        {
            normalized.inputDeviceName = normalizedInput;
            changed = true;
        }

        string normalizedOutput = NormalizeSharedAudioStoredSelection(normalized.outputDeviceName);
        if (!string.Equals(normalized.outputDeviceName, normalizedOutput, StringComparison.Ordinal))
        {
            normalized.outputDeviceName = normalizedOutput;
            changed = true;
        }

        int normalizedSampleRate = SharedAudioSampleRateOptions.Normalize(normalized.sampleRate);
        if (normalized.sampleRate != normalizedSampleRate)
        {
            normalized.sampleRate = normalizedSampleRate;
            changed = true;
        }

        int safeFallbackBuffer = NormalizeSharedMonitoringBufferSize(fallbackBufferSize);
        int normalizedBuffer = normalized.bufferSize <= 0
            ? safeFallbackBuffer
            : NormalizeSharedMonitoringBufferSize(normalized.bufferSize);
        if (normalized.bufferSize != normalizedBuffer)
        {
            normalized.bufferSize = normalizedBuffer;
            changed = true;
        }

        return normalized;
    }

    private static string ResolveChoiceLabel(IReadOnlyList<string> choices, string storedValue)
    {
        if (IsSharedAudioAutomaticValue(storedValue))
            return SharedAudioAutomaticLabel;

        string resolvedChoice = ResolveChoiceByNormalizedName(choices, storedValue);
        if (!string.IsNullOrWhiteSpace(resolvedChoice))
            return resolvedChoice;

        return SharedAudioSettingsUtility.NormalizeStoredDeviceName(storedValue);
    }

    private string ResolveNativeDetectorInputDeviceName(int deviceIndex)
    {
        for (int i = 0; i < nativeNotesDetectorInputDevices.Count; i++)
        {
            NativeDetectorInputDevice device = nativeNotesDetectorInputDevices[i];
            if (device != null && device.index == deviceIndex)
                return ResolveNativeDetectorInputDeviceDisplayLabel(device);
        }

        return string.Empty;
    }

    private static string ResolveNativeDetectorInputDeviceDisplayLabel(NativeDetectorInputDevice device)
    {
        if (device == null)
            return string.Empty;

        return string.IsNullOrWhiteSpace(device.displayName) ? device.name?.Trim() ?? string.Empty : device.displayName.Trim();
    }

    private string ResolveToneLabSharedDeviceName(string storedValue, IReadOnlyList<string> availableDevices)
    {
        if (IsSharedAudioAutomaticValue(storedValue))
            return string.Empty;

        string resolvedDevice = ResolveChoiceByNormalizedName(availableDevices, storedValue);
        if (!string.IsNullOrWhiteSpace(resolvedDevice))
            return resolvedDevice;

        return SharedAudioSettingsUtility.NormalizeStoredDeviceName(storedValue);
    }

    private int ResolveNativeDetectorSharedDeviceIndex(string storedValue)
    {
        if (IsSharedAudioAutomaticValue(storedValue))
            return -1;

        string normalizedStored = SharedAudioSettingsUtility.NormalizeDeviceKey(storedValue);
        string physicalStored = SharedAudioSettingsUtility.NormalizePhysicalDeviceKey(storedValue);
        int bestIndex = -1;
        int bestRank = int.MaxValue;
        int bestExactPenalty = int.MaxValue;
        for (int i = 0; i < nativeNotesDetectorInputDevices.Count; i++)
        {
            NativeDetectorInputDevice device = nativeNotesDetectorInputDevices[i];
            string displayName = ResolveNativeDetectorInputDeviceDisplayLabel(device);
            bool exactMatch = string.Equals(SharedAudioSettingsUtility.NormalizeDeviceKey(displayName), normalizedStored, StringComparison.Ordinal);
            bool physicalMatch = !string.IsNullOrWhiteSpace(physicalStored) &&
                string.Equals(SharedAudioSettingsUtility.NormalizePhysicalDeviceKey(displayName), physicalStored, StringComparison.Ordinal);
            if (!exactMatch && !physicalMatch)
                continue;

            int rank = GetNativeDetectorSharedDeviceHostRank(device);
            int exactPenalty = exactMatch ? 0 : 1;
            int deviceIndex = device?.index ?? -1;
            if (rank < bestRank ||
                (rank == bestRank && exactPenalty < bestExactPenalty) ||
                (rank == bestRank && exactPenalty == bestExactPenalty && deviceIndex >= 0 && (bestIndex < 0 || deviceIndex < bestIndex)))
            {
                bestIndex = deviceIndex;
                bestRank = rank;
                bestExactPenalty = exactPenalty;
            }
        }

        return bestIndex;
    }

    private static int GetNativeDetectorSharedDeviceHostRank(NativeDetectorInputDevice device)
    {
        string host = device?.hostApiName ?? string.Empty;
        if (host.IndexOf("ASIO", StringComparison.OrdinalIgnoreCase) >= 0 ||
            host.IndexOf("Core Audio", StringComparison.OrdinalIgnoreCase) >= 0 ||
            host.IndexOf("CoreAudio", StringComparison.OrdinalIgnoreCase) >= 0)
        {
            return 0;
        }

        if (host.IndexOf("WASAPI", StringComparison.OrdinalIgnoreCase) >= 0)
            return 1;
        if (host.IndexOf("DirectSound", StringComparison.OrdinalIgnoreCase) >= 0)
            return 2;
        if (host.IndexOf("MME", StringComparison.OrdinalIgnoreCase) >= 0)
            return 3;
        if (host.IndexOf("WDM", StringComparison.OrdinalIgnoreCase) >= 0 ||
            host.IndexOf("Kernel", StringComparison.OrdinalIgnoreCase) >= 0)
        {
            return 5;
        }
        if (host.IndexOf("Windows", StringComparison.OrdinalIgnoreCase) >= 0)
            return 4;

        return 6;
    }

    private int RefreshSelectedNativeDetectorInputDeviceFromSharedSettings(bool savePreference)
    {
        selectedNativeNotesDetectorInputDeviceIndex = ResolveNativeDetectorSharedDeviceIndex(sharedAudioSettings?.inputDeviceName);
        if (savePreference)
            SaveNativeDetectorPreferences();
        return selectedNativeNotesDetectorInputDeviceIndex;
    }

    private void ApplySharedAudioSettingsToSubsystems(bool restartDetector, bool restartToneLab, bool refreshCatalogs)
    {
        EnsureToneLabRuntimeComponent();
        if (refreshCatalogs)
            RefreshSharedAudioRoutingCatalogs(refreshToneLabDevices: true, refreshDetectorDevices: true);

        if (sharedAudioSettings == null)
            sharedAudioSettings = new SharedAudioSettings();

        int monitoringBufferSize = NormalizeSharedMonitoringBufferSize(sharedAudioSettings.monitoringBufferSize);
        sharedAudioSettings.monitoringBufferSize = monitoringBufferSize;
        sharedAudioSettings.songVolumePercent = Mathf.Clamp(sharedAudioSettings.songVolumePercent, 0f, 100f);
        sharedAudioSettings.guitarVolumePercent = Mathf.Clamp(sharedAudioSettings.guitarVolumePercent, 0f, UnityToneLabRuntime.MaxMonitorVolumePercent);
        sharedAudioSettings.detectorResamplerMode = SharedAudioDetectorResamplerModes.Normalize(sharedAudioSettings.detectorResamplerMode);
        SharedAudioAdvancedSettings advancedSettings = NormalizeSharedAudioAdvancedSettings(sharedAudioSettings.advanced, monitoringBufferSize, out _);
        sharedAudioSettings.advanced = advancedSettings;

        if (unityToneLabRuntime != null)
        {
            string resolvedToneLabInput = ResolveToneLabSharedDeviceName(sharedAudioSettings.inputDeviceName, unityToneLabRuntime.InputDevices);
            string resolvedToneLabOutput = ResolveToneLabSharedDeviceName(sharedAudioSettings.outputDeviceName, unityToneLabRuntime.OutputDevices);
            if (advancedSettings.betaEnabled)
            {
                string advancedInputDisplay = ResolveToneLabDisplayNameFromAdvancedSelection(advancedSettings.inputDeviceName, unityToneLabRuntime.InputDevices);
                string advancedOutputDisplay = ResolveToneLabDisplayNameFromAdvancedSelection(advancedSettings.outputDeviceName, unityToneLabRuntime.OutputDevices);
                if (!string.IsNullOrWhiteSpace(advancedInputDisplay))
                    resolvedToneLabInput = advancedInputDisplay;
                if (!string.IsNullOrWhiteSpace(advancedOutputDisplay))
                    resolvedToneLabOutput = advancedOutputDisplay;
                monitoringBufferSize = NormalizeSharedMonitoringBufferSize(advancedSettings.bufferSize);
                sharedAudioSettings.monitoringBufferSize = monitoringBufferSize;
            }

            unityToneLabRuntime.SetAdvancedRoutingOptions(new UnityToneLabRuntime.AdvancedRoutingOptions
            {
                betaEnabled = advancedSettings.betaEnabled,
                inputChannelMode = advancedSettings.inputChannelMode,
                backendMode = advancedSettings.backendMode,
                allowFallback = advancedSettings.allowFallback,
                preferredInputDeviceName = advancedSettings.inputDeviceName,
                preferredOutputDeviceName = advancedSettings.outputDeviceName,
                sampleRate = advancedSettings.sampleRate,
                bufferSize = advancedSettings.bufferSize,
                splitInputOutputEnabled = advancedSettings.splitInputOutputEnabled,
                unifiedOutputEnabled = advancedSettings.unifiedOutputEnabled,
                unityRecorderCaptureEnabled = advancedSettings.unityRecorderCaptureEnabled
            });
            unityToneLabRuntime.UpdateSettings(settings =>
            {
                settings.input_device_name = resolvedToneLabInput;
                settings.output_device_name = resolvedToneLabOutput;
                settings.monitoring_buffer_size = monitoringBufferSize;
            }, restartMonitoring: restartToneLab);
            unityToneLabRuntime.SetMonitorVolumePercent(sharedAudioSettings.guitarVolumePercent);
        }

        if (notesDetectorBackendMode == NotesDetectorBackendMode.NativeEmbeddedBridge)
        {
            EnsureNativeNotesDetectorBridge();
            nativeNotesDetectorBridge?.SetInputChannelMode(advancedSettings.inputChannelMode);
            nativeNotesDetectorBridge?.SetResamplerMode(ParseSharedDetectorResamplerMode(sharedAudioSettings.detectorResamplerMode));
        }

        int previousNativeDetectorInputDeviceIndex = selectedNativeNotesDetectorInputDeviceIndex;
        RefreshSelectedNativeDetectorInputDeviceFromSharedSettings(savePreference: true);
        bool nativeDetectorInputDeviceChanged = previousNativeDetectorInputDeviceIndex != selectedNativeNotesDetectorInputDeviceIndex;

        bool shouldRestartDetectorForDeviceChange = nativeDetectorInputDeviceChanged && nativeNotesDetectorBridge?.IsRunning() == true;
        if ((restartDetector || shouldRestartDetectorForDeviceChange) && notesDetectorBackendMode == NotesDetectorBackendMode.NativeEmbeddedBridge)
        {
            EnsureNativeNotesDetectorBridge();
            StartConfiguredNotesDetectorBackend();
        }

        RefreshNativeNotesDetectorUiState();
        runtimeSettingsSnapshotDirty = true;
        MarkDetectorHintDirty();

        if (restartDetector || restartToneLab || refreshCatalogs)
            LogFullDiagnosticsSnapshot("shared-audio-settings-applied", includeEnvironment: false);
    }

    public IReadOnlyList<string> GetSharedAudioInputDeviceChoices()
    {
        return sharedAudioInputDeviceChoices;
    }

    public IReadOnlyList<string> GetSharedAudioOutputDeviceChoices()
    {
        return sharedAudioOutputDeviceChoices;
    }

    public string GetSharedAudioSelectedInputLabel()
    {
        if (sharedAudioSettings?.advanced?.betaEnabled == true)
        {
            string advancedChoice = ResolveChoiceByNormalizedName(
                sharedAudioInputDeviceChoices,
                StripAdvancedAudioDeviceDecorations(sharedAudioSettings.advanced.inputDeviceName));
            if (!string.IsNullOrWhiteSpace(advancedChoice))
                return advancedChoice;
        }

        return ResolveChoiceLabel(sharedAudioInputDeviceChoices, sharedAudioSettings?.inputDeviceName);
    }

    public string GetSharedAudioSelectedOutputLabel()
    {
        if (sharedAudioSettings?.advanced?.betaEnabled == true)
        {
            string advancedChoice = ResolveChoiceByNormalizedName(
                sharedAudioOutputDeviceChoices,
                StripAdvancedAudioDeviceDecorations(sharedAudioSettings.advanced.outputDeviceName));
            if (!string.IsNullOrWhiteSpace(advancedChoice))
                return advancedChoice;
        }

        return ResolveChoiceLabel(sharedAudioOutputDeviceChoices, sharedAudioSettings?.outputDeviceName);
    }

    public string GetSharedAudioSelectedLatencyLabel()
    {
        if (sharedAudioSettings?.advanced?.betaEnabled == true)
            return UnityToneLabRuntime.GetSharedMonitoringLatencyLabel(sharedAudioSettings.advanced.bufferSize);

        return UnityToneLabRuntime.GetSharedMonitoringLatencyLabel(sharedAudioSettings?.monitoringBufferSize ?? 128);
    }

    public string GetSharedAudioInputChannelModeLabel()
    {
        return SharedAudioInputChannelModes.Normalize(sharedAudioSettings?.advanced?.inputChannelMode);
    }

    public float GetSharedAudioGuitarVolumePercent()
    {
        return Mathf.Clamp(sharedAudioSettings?.guitarVolumePercent ?? 100f, 0f, UnityToneLabRuntime.MaxMonitorVolumePercent);
    }

    public float GetToneLabGlobalInputGainDb()
    {
        EnsureToneLabRuntimeComponent();
