    private static bool IsAnyGamepadSecondaryActionPressedThisFrame()
    {
#if ENABLE_INPUT_SYSTEM
        foreach (Gamepad gamepad in Gamepad.all)
        {
            if (gamepad?.buttonEast.wasPressedThisFrame == true)
                return true;
        }
