        RegisterFloatSetting("bg.neonHorizon.coreGlow", section, "Core Glow", "Intensity of the thin bright horizon core.", 0f, 5f, 0.05f, () => neonHorizonCoreGlowIntensity, v => neonHorizonCoreGlowIntensity = Mathf.Max(0f, v));
