    private void RegisterEnviroMoodPresetRuntimeSettings(string section)
    {
        EnsureEnviroMoodSettings();
        for (int moodIndex = 0; moodIndex < EnviroSkyMoodOptions.Length; moodIndex++)
        {
            int capturedMoodIndex = moodIndex;
            RegisterEnumSetting(
                GetEnviroMoodSettingId(capturedMoodIndex, "moonMode"),
                section,
                "Enviro Moon",
                "Overrides the moon for this Enviro 3 mood only. Normal keeps the mood-authored moon size and visibility.",
                EnviroMoonModeOptions,
                () => GetIndexedOption(EnviroMoonModeOptions, (int)GetEnviroMoonModeForMood(capturedMoodIndex)),
                value => SetEnviroMoonModeForMood(capturedMoodIndex, (TabsEnviroMoonMode)Mathf.Clamp(ParseIndexedOption(EnviroMoonModeOptions, value, (int)GetEnviroMoonModeForMood(capturedMoodIndex)), 0, EnviroMoonModeOptions.Length - 1)));

            RegisterEnumSetting(
                GetEnviroMoodSettingId(capturedMoodIndex, "groundMode"),
                section,
                "Enviro Ground",
                "Chooses the ground treatment for this Enviro 3 mood only: none, a flat plane, an extended plane, or distant mountain silhouettes.",
                EnviroGroundModeOptions,
                () => GetIndexedOption(EnviroGroundModeOptions, (int)GetEnviroGroundModeForMood(capturedMoodIndex)),
                value => SetEnviroGroundModeForMood(capturedMoodIndex, (TabsEnviroGroundMode)ParseEnviroGroundModeOption(value, (int)GetEnviroGroundModeForMood(capturedMoodIndex))));

            RegisterFloatSetting(
                GetEnviroMoodSettingId(capturedMoodIndex, "skyCameraPitch"),
                section,
                "Sky Camera Pitch",
                "Tilts Enviro 3 sky and volumetric cloud sampling for this mood without rotating the gameplay camera. Positive values look higher into the sky.",
                -18f,
                18f,
                0.5f,
                () => GetEnviroSkyCameraPitchForMood(capturedMoodIndex),
                value => SetEnviroSkyCameraPitchForMood(capturedMoodIndex, value));

            RegisterFloatSetting(
                GetEnviroMoodSettingId(capturedMoodIndex, "starAnimation"),
                section,
                "Star Animation",
                "Boosts this mood's Enviro 3 star brightness and twinkle speed so the sky reads as more alive. 1 keeps the authored look.",
                0f,
                2f,
                0.05f,
                () => GetEnviroStarAnimationForMood(capturedMoodIndex),
                value => SetEnviroStarAnimationForMood(capturedMoodIndex, value));

            RegisterFloatSetting(
                GetEnviroMoodSettingId(capturedMoodIndex, "starDensity"),
                section,
                "Star Density",
                "Controls how many stars this Enviro 3 mood appears to have. 1 keeps the authored density; higher values add a denser procedural star layer.",
                0f,
                2f,
                0.05f,
                () => GetEnviroStarDensityForMood(capturedMoodIndex),
                value => SetEnviroStarDensityForMood(capturedMoodIndex, value));

            RegisterFloatSetting(
                GetEnviroMoodSettingId(capturedMoodIndex, "mountainOpacity"),
                section,
                "Mountain Opacity Legacy",
                "Legacy mountain opacity. New moods use the separate near, middle, and far mountain layer opacity controls.",
                0f,
                1f,
                0.05f,
                () => GetEnviroMountainOpacityForMood(capturedMoodIndex),
                value => SetEnviroMountainOpacityForMood(capturedMoodIndex, value));

            RegisterFloatSetting(
                GetEnviroMoodSettingId(capturedMoodIndex, "mountainOpacityNear"),
                section,
                "Near Mountain Opacity",
                "Controls the closest, darkest mountain layer for this Enviro 3 mood only.",
                0f,
                1f,
                0.05f,
                () => GetEnviroMountainLayerOpacityForMood(capturedMoodIndex, 2),
                value => SetEnviroMountainLayerOpacityForMood(capturedMoodIndex, 2, value));

            RegisterFloatSetting(
                GetEnviroMoodSettingId(capturedMoodIndex, "mountainOpacityMid"),
                section,
                "Middle Mountain Opacity",
                "Controls the middle mountain layer for this Enviro 3 mood only.",
                0f,
                1f,
                0.05f,
                () => GetEnviroMountainLayerOpacityForMood(capturedMoodIndex, 1),
                value => SetEnviroMountainLayerOpacityForMood(capturedMoodIndex, 1, value));

            RegisterFloatSetting(
                GetEnviroMoodSettingId(capturedMoodIndex, "mountainOpacityFar"),
                section,
                "Far Mountain Opacity",
                "Controls the farthest, softest mountain layer for this Enviro 3 mood only.",
                0f,
                1f,
                0.05f,
                () => GetEnviroMountainLayerOpacityForMood(capturedMoodIndex, 0),
                value => SetEnviroMountainLayerOpacityForMood(capturedMoodIndex, 0, value));

            RegisterBoolSetting(
                GetEnviroMoodSettingId(capturedMoodIndex, "clouds"),
                section,
                "Volumetric Clouds",
                "Turns Enviro 3 volumetric clouds on or off for this mood only.",
                () => GetEnviroCloudsEnabledForMood(capturedMoodIndex),
                value => SetEnviroCloudsEnabledForMood(capturedMoodIndex, value));

            RegisterFloatSetting(
                GetEnviroMoodSettingId(capturedMoodIndex, "cloudAmount"),
                section,
                "Cloud Amount",
                "Adds or removes Enviro 3 volumetric cloud coverage for this mood only.",
                0f,
                2f,
                0.05f,
                () => GetEnviroCloudAmountForMood(capturedMoodIndex),
                value => SetEnviroCloudAmountForMood(capturedMoodIndex, value));

            RegisterFloatSetting(
                GetEnviroMoodSettingId(capturedMoodIndex, "cloudThickness"),
                section,
                "Cloud Thickness",
                "Controls how dense and physically heavy this mood's Enviro 3 cloud volume feels.",
                0f,
                2f,
                0.05f,
                () => GetEnviroCloudThicknessForMood(capturedMoodIndex),
                value => SetEnviroCloudThicknessForMood(capturedMoodIndex, value));

            RegisterFloatSetting(
                GetEnviroMoodSettingId(capturedMoodIndex, "cloudConnectivity"),
                section,
                "Cloud Connection",
                "Moves this mood's Enviro 3 clouds between broken islands and more connected cloud banks.",
                0f,
                2f,
                0.05f,
                () => GetEnviroCloudConnectivityForMood(capturedMoodIndex),
                value => SetEnviroCloudConnectivityForMood(capturedMoodIndex, value));

            RegisterFloatSetting(
                GetEnviroMoodSettingId(capturedMoodIndex, "cloudContrast"),
                section,
                "Cloud Contrast",
                "Controls the split between bright moon/sun-lit edges and the darker cloud body for this mood.",
                0f,
                2f,
                0.05f,
                () => GetEnviroCloudContrastForMood(capturedMoodIndex),
                value => SetEnviroCloudContrastForMood(capturedMoodIndex, value));
        }
    }

    private static string GetIndexedOption(string[] options, int index)
    {
        if (options == null || options.Length == 0)
            return string.Empty;

        return options[Mathf.Clamp(index, 0, options.Length - 1)];
    }

    private static string SerializeBackgroundMode(TabsBackgroundMode mode)
    {
        switch (mode)
        {
            case TabsBackgroundMode.BlueSky:
                return nameof(TabsBackgroundMode.BlueSky);
            case TabsBackgroundMode.NeonStage:
                return nameof(TabsBackgroundMode.NeonStage);
            case TabsBackgroundMode.SolidColor:
                return nameof(TabsBackgroundMode.SolidColor);
            default:
                return nameof(TabsBackgroundMode.NeonStage);
        }
    }

    private static TabsBackgroundMode ParseBackgroundMode(string value, TabsBackgroundMode fallback)
    {
        if (Enum.TryParse(value, out TabsBackgroundMode mode))
        {
            switch (mode)
            {
                case TabsBackgroundMode.SolidColor:
                case TabsBackgroundMode.BlueSky:
                case TabsBackgroundMode.NeonStage:
                    return mode;
            }
        }

        return fallback == TabsBackgroundMode.SolidColor || fallback == TabsBackgroundMode.BlueSky || fallback == TabsBackgroundMode.NeonStage
            ? fallback
            : TabsBackgroundMode.NeonStage;
    }

    private int GetNeonStageSkyDesignOptionIndex()
    {
        return neonStageSkyDesign == TabsNeonStageSkyDesign.Enviro3 ? 1 : 0;
    }

    private void SetNeonStageSkyDesignFromOptionIndex(int optionIndex)
    {
        neonStageSkyDesign = optionIndex == 1
            ? TabsNeonStageSkyDesign.Enviro3
            : TabsNeonStageSkyDesign.ProceduralDome;
    }

    private static int ParseIndexedOption(string[] options, string value, int fallback)
    {
        if (options == null || options.Length == 0)
            return 0;

        if (!string.IsNullOrWhiteSpace(value))
        {
            for (int i = 0; i < options.Length; i++)
            {
                if (string.Equals(options[i], value, StringComparison.OrdinalIgnoreCase))
                    return i;
            }
        }

        return Mathf.Clamp(fallback, 0, options.Length - 1);
    }

    private static int ParseEnviroGroundModeOption(string value, int fallback)
    {
        string normalized = (value ?? string.Empty).Trim();
        if (string.Equals(normalized, "FlatPlane", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(normalized, "Flat Plane", StringComparison.OrdinalIgnoreCase))
            return (int)TabsEnviroGroundMode.FlatPlane;
        if (string.Equals(normalized, "ExtendedPlane", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(normalized, "Extended Plane", StringComparison.OrdinalIgnoreCase))
            return (int)TabsEnviroGroundMode.ExtendedPlane;
        if (string.Equals(normalized, "Mountains", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(normalized, "Distant Mountains", StringComparison.OrdinalIgnoreCase))
            return (int)TabsEnviroGroundMode.Mountains;
        if (string.Equals(normalized, "Off", StringComparison.OrdinalIgnoreCase))
            return (int)TabsEnviroGroundMode.Off;

        return ParseIndexedOption(EnviroGroundModeOptions, normalized, fallback);
    }

    private static string SerializeRenderMode(GuitarRenderMode mode)
    {
        switch (mode)
        {
            case GuitarRenderMode.Tabs:
            case GuitarRenderMode.TabsAlphaTab:
                return "Tabs";
            case GuitarRenderMode.Highway3DAndTabs:
                return "3D + Tabs";
            case GuitarRenderMode.Highway3D:
            default:
                return "Highway3D";
        }
    }

    private static GuitarRenderMode ParseRenderMode(string value)
    {
        switch ((value ?? string.Empty).Trim())
        {
            case "Tabs":
            case "Tabs (AlphaTab)":
                return GuitarRenderMode.TabsAlphaTab;
            case "3D + Tabs":
                return GuitarRenderMode.Highway3DAndTabs;
            case "Highway3D":
            default:
                return GuitarRenderMode.Highway3D;
        }
    }

    private static string SerializeHighwayCameraEngine(HighwayCameraEngine engine)
    {
        return engine == HighwayCameraEngine.SmartLookahead ? "Smart Lookahead" : "Legacy";
    }

    private static HighwayCameraEngine ParseHighwayCameraEngine(string value)
    {
        string normalized = (value ?? string.Empty).Trim();
        if (string.Equals(normalized, "Smart Lookahead", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(normalized, "SmartLookahead", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(normalized, "Camera Engine V2", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(normalized, "V2", StringComparison.OrdinalIgnoreCase))
            return HighwayCameraEngine.SmartLookahead;

        return HighwayCameraEngine.Legacy;
    }

    private bool CanUseAlphaTabRenderMode()
    {
        return TryGetCurrentAlphaTabRenderTarget(out _, out _);
    }

    public bool TryGetCurrentAlphaTabRenderTarget(out string notationPath, out int trackIndex)
    {
        notationPath = string.Empty;
        trackIndex = -1;

        if (currentSongEntry == null)
            return false;

        if (currentSongEntry.PrimaryNotationKind == SongNotationSourceKind.ArrangementCache &&
            !string.IsNullOrWhiteSpace(currentSongEntry.PrimaryNotationPath) &&
            File.Exists(currentSongEntry.PrimaryNotationPath))
        {
            notationPath = currentSongEntry.PrimaryNotationPath;
            trackIndex = Mathf.Max(0, GetResolvedActiveTrackSummary()?.Index ?? 0);
            return true;
        }

        string gpPath = string.Empty;
        if (currentSongEntry.PrimaryNotationKind == SongNotationSourceKind.Gp5 &&
            !string.IsNullOrWhiteSpace(currentSongEntry.PrimaryNotationPath) &&
            File.Exists(currentSongEntry.PrimaryNotationPath))
        {
            gpPath = currentSongEntry.PrimaryNotationPath;
        }
        else if (!string.IsNullOrWhiteSpace(currentSongEntry.GpPath) &&
                 File.Exists(currentSongEntry.GpPath) &&
                 !string.IsNullOrWhiteSpace(selectedMusicXmlPartId) &&
                 selectedMusicXmlPartId.StartsWith("gp5-track-", StringComparison.OrdinalIgnoreCase))
        {
            gpPath = currentSongEntry.GpPath;
        }

        if (string.IsNullOrWhiteSpace(gpPath))
            return false;

        notationPath = gpPath;
        trackIndex = Mathf.Max(0, ResolveCurrentAlphaTabTrackIndex());
        return true;
    }

    private int ResolveCurrentAlphaTabTrackIndex()
    {
        if (!string.IsNullOrWhiteSpace(selectedMusicXmlPartId) &&
            selectedMusicXmlPartId.StartsWith("gp5-track-", StringComparison.OrdinalIgnoreCase))
        {
            string suffix = selectedMusicXmlPartId.Substring("gp5-track-".Length);
            if (int.TryParse(suffix, NumberStyles.Integer, CultureInfo.InvariantCulture, out int parsedTrackIndex))
                return Mathf.Max(0, parsedTrackIndex);
        }

        return Mathf.Max(0, midiTrackIndex);
    }

    private void RegisterFloatSetting(string id, string section, string label, string tooltip, float min, float max, float step, Func<float> getter, Action<float> setter)
    {
        RegisterSetting(new RuntimeSettingDefinition
        {
            Id = id,
            Section = section,
            Label = label,
            Tooltip = tooltip,
            ValueType = "float",
            Min = min,
            Max = max,
            Step = step,
            Getter = () => getter().ToString("0.###", CultureInfo.InvariantCulture),
            Setter = value =>
            {
                if (!float.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out float parsed))
                    return;
                setter(Mathf.Clamp(parsed, min, max));
            }
        });
    }

    private void RegisterIntSetting(string id, string section, string label, string tooltip, int min, int max, int step, Func<int> getter, Action<int> setter)
    {
        RegisterSetting(new RuntimeSettingDefinition
        {
            Id = id,
            Section = section,
            Label = label,
            Tooltip = tooltip,
            ValueType = "int",
            Min = min,
            Max = max,
            Step = Mathf.Max(1, step),
            Getter = () => getter().ToString(CultureInfo.InvariantCulture),
            Setter = value =>
            {
                if (!int.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out int parsed))
                    return;
                setter(Mathf.Clamp(parsed, min, max));
            }
        });
    }

    private void RegisterBoolSetting(string id, string section, string label, string tooltip, Func<bool> getter, Action<bool> setter)
    {
        RegisterSetting(new RuntimeSettingDefinition
        {
            Id = id,
            Section = section,
            Label = label,
            Tooltip = tooltip,
            ValueType = "bool",
            Getter = () => getter() ? "true" : "false",
            Setter = value =>
            {
                if (!bool.TryParse(value, out bool parsed))
                    return;
                setter(parsed);
            }
        });
    }

    private void RegisterEnumSetting(string id, string section, string label, string tooltip, IEnumerable<string> options, Func<string> getter, Action<string> setter)
    {
        RegisterSetting(new RuntimeSettingDefinition
        {
            Id = id,
            Section = section,
            Label = label,
            Tooltip = tooltip,
            ValueType = "enum",
            EnumOptions = options.ToList(),
            Getter = getter,
            Setter = setter
        });
    }

    private void RegisterBindingSetting(string id, string section, string label, string tooltip, Func<KeyCode> getter, Action<KeyCode> setter, ArcadeBindingCaptureKind captureKind)
    {
        RegisterSetting(new RuntimeSettingDefinition
        {
            Id = id,
            Section = section,
            Label = label,
            Tooltip = tooltip,
            ValueType = "binding",
            Getter = () =>
            {
                if (string.Equals(activeArcadeBindingSettingId, id, StringComparison.OrdinalIgnoreCase))
                    return captureKind == ArcadeBindingCaptureKind.Controller ? "PRESS A CONTROLLER INPUT" : "PRESS A KEY";
                return SerializeArcadeBinding(getter());
            },
            Setter = value => setter(ParseArcadeBinding(value, getter())),
            Activator = () => BeginArcadeBindingCapture(id),
            BindingCaptureKind = captureKind
        });
    }

    private void RegisterActionSetting(string id, string section, string label, string tooltip, string valueLabel, Action activator)
    {
        RegisterSetting(new RuntimeSettingDefinition
        {
            Id = id,
            Section = section,
            Label = label,
            Tooltip = tooltip,
            ValueType = "action",
            Getter = () => string.IsNullOrWhiteSpace(valueLabel) ? "RUN" : valueLabel,
            Setter = null,
            Activator = activator
        });
    }

    private void RegisterSetting(RuntimeSettingDefinition definition)
    {
        if (definition == null || string.IsNullOrEmpty(definition.Id))
            return;

        definition.VisibleInGlobalSettings = ShouldShowRuntimeSettingInGlobalSettings(definition.Id);
        runtimeSettingDefinitions.Add(definition);
        runtimeSettingById[definition.Id] = definition;
        runtimeSettingDefaultValues[definition.Id] = definition.Getter != null ? definition.Getter() : string.Empty;
        runtimeSettingsSnapshotDirty = true;
    }

    private static bool ShouldShowRuntimeSettingInGlobalSettings(string settingId)
    {
        if (string.IsNullOrWhiteSpace(settingId))
            return true;

        if (string.Equals(settingId, "bg.moodSetter", StringComparison.OrdinalIgnoreCase))
            return true;

        if (settingId.StartsWith("bg.", StringComparison.OrdinalIgnoreCase))
            return false;

        if (settingId.StartsWith("highway.background", StringComparison.OrdinalIgnoreCase) ||
            settingId.StartsWith("highway.cloud", StringComparison.OrdinalIgnoreCase) ||
            settingId.StartsWith("highway.star", StringComparison.OrdinalIgnoreCase))
            return false;

        return true;
    }

    private static string SerializeArcadeInputSource(ArcadeInputSourceMode source)
    {
        switch (source)
        {
            case ArcadeInputSourceMode.Keyboard:
                return "Keyboard";
            case ArcadeInputSourceMode.Controller:
                return "Controller";
            case ArcadeInputSourceMode.Midi:
                return "MIDI";
            case ArcadeInputSourceMode.All:
                return "All";
            default:
                return "Keyboard + Controller";
        }
    }

    private static List<string> BuildArcadeControllerDeviceOptions()
    {
        List<string> options = new List<string> { "Any Connected Controller" };
        string[] joystickNames = Input.GetJoystickNames();
        for (int i = 0; i < ArcadeControllerSlotCount; i++)
        {
            string deviceName = joystickNames != null && i < joystickNames.Length ? joystickNames[i] : string.Empty;
            string label = string.IsNullOrWhiteSpace(deviceName)
                ? $"Joystick {i + 1}"
                : $"Joystick {i + 1} ({deviceName.Trim()})";
            options.Add(label);
        }

        return options;
    }

    private string SerializeArcadeControllerDevice()
    {
        List<string> options = BuildArcadeControllerDeviceOptions();
        int index = Mathf.Clamp(arcadeControllerDeviceIndex, 0, options.Count - 1);
        return options[index];
    }

    private static int ParseArcadeControllerDevice(string value)
    {
        if (string.IsNullOrWhiteSpace(value) || value.StartsWith("Any", StringComparison.OrdinalIgnoreCase))
            return 0;

        Match match = Regex.Match(value, @"Joystick\s+(\d+)", RegexOptions.CultureInvariant | RegexOptions.IgnoreCase);
        if (match.Success && int.TryParse(match.Groups[1].Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out int parsed))
            return Mathf.Clamp(parsed, 0, ArcadeControllerSlotCount);

        return 0;
    }

    private static ArcadeInputSourceMode ParseArcadeInputSource(string value)
    {
        if (string.Equals(value, "Keyboard", StringComparison.OrdinalIgnoreCase))
            return ArcadeInputSourceMode.Keyboard;
        if (string.Equals(value, "Controller", StringComparison.OrdinalIgnoreCase))
            return ArcadeInputSourceMode.Controller;
        if (string.Equals(value, "MIDI", StringComparison.OrdinalIgnoreCase))
            return ArcadeInputSourceMode.Midi;
        if (string.Equals(value, "All", StringComparison.OrdinalIgnoreCase))
            return ArcadeInputSourceMode.All;
        return ArcadeInputSourceMode.KeyboardAndController;
    }

    private static string SerializeArcadeBinding(KeyCode binding)
    {
        return binding == KeyCode.None ? "None" : NormalizeArcadeBinding(binding).ToString();
    }

    private static KeyCode ParseArcadeBinding(string value, KeyCode fallback)
    {
        if (string.IsNullOrWhiteSpace(value))
            return fallback;
        if (string.Equals(value, "None", StringComparison.OrdinalIgnoreCase))
            return KeyCode.None;
        return Enum.TryParse(value, true, out KeyCode parsed) ? NormalizeArcadeBinding(parsed) : fallback;
    }

    private static KeyCode NormalizeArcadeBinding(KeyCode binding)
    {
        string name = binding.ToString();
        Match specificJoystickMatch = Regex.Match(name, @"^Joystick\d+Button(\d+)$", RegexOptions.CultureInvariant);
        if (specificJoystickMatch.Success && Enum.TryParse($"JoystickButton{specificJoystickMatch.Groups[1].Value}", out KeyCode normalized))
            return normalized;
        return binding;
    }

    private void ResetArcadeKeyboardBindingsToDefaults()
    {
        arcadeKeyboardGreen = KeyCode.A;
        arcadeKeyboardRed = KeyCode.S;
        arcadeKeyboardYellow = KeyCode.J;
        arcadeKeyboardBlue = KeyCode.K;
        arcadeKeyboardOrange = KeyCode.L;
        arcadeKeyboardStrumUp = KeyCode.Space;
        arcadeKeyboardStrumDown = KeyCode.None;
        arcadeKeyboardOpen = KeyCode.None;
        runtimeSettingsSnapshotDirty = true;
    }

    private void ResetArcadeControllerBindingsToDefaults()
    {
        arcadeControllerGreen = KeyCode.JoystickButton6;
        arcadeControllerRed = KeyCode.JoystickButton4;
        arcadeControllerYellow = KeyCode.JoystickButton5;
        arcadeControllerBlue = KeyCode.JoystickButton7;
        arcadeControllerOrange = KeyCode.JoystickButton0;
        arcadeControllerStrumUp = KeyCode.JoystickButton13;
        arcadeControllerStrumDown = KeyCode.JoystickButton14;
        arcadeControllerOpen = KeyCode.JoystickButton8;
        runtimeSettingsSnapshotDirty = true;
    }

    private void BeginArcadeBindingCapture(string settingId)
    {
        if (string.IsNullOrWhiteSpace(settingId) || !runtimeSettingById.TryGetValue(settingId, out RuntimeSettingDefinition definition) || definition.BindingCaptureKind == ArcadeBindingCaptureKind.None)
            return;

        activeArcadeBindingSettingId = settingId;
        activeArcadeBindingStartFrame = Time.frameCount;
        runtimeSettingsSnapshotDirty = true;
    }

    private void CancelArcadeBindingCapture()
    {
        if (string.IsNullOrEmpty(activeArcadeBindingSettingId))
            return;

        activeArcadeBindingSettingId = string.Empty;
        activeArcadeBindingStartFrame = -1;
        runtimeSettingsSnapshotDirty = true;
    }

    private bool HandleArcadeBindingCaptureInput()
    {
        if (string.IsNullOrEmpty(activeArcadeBindingSettingId))
            return false;

        if (Time.frameCount <= activeArcadeBindingStartFrame)
            return true;

        if (Input.GetKeyDown(KeyCode.Escape))
        {
            CancelArcadeBindingCapture();
            return true;
        }

        if (Input.GetKeyDown(KeyCode.Delete))
        {
            ApplyRuntimeSettingValue(activeArcadeBindingSettingId, "None", saveMetadata: true);
            CancelArcadeBindingCapture();
            return true;
        }

        if (!runtimeSettingById.TryGetValue(activeArcadeBindingSettingId, out RuntimeSettingDefinition definition))
        {
            CancelArcadeBindingCapture();
            return true;
        }

        if (TryGetPressedArcadeBinding(definition.BindingCaptureKind, out KeyCode binding))
        {
            ApplyRuntimeSettingValue(activeArcadeBindingSettingId, SerializeArcadeBinding(binding), saveMetadata: true);
            CancelArcadeBindingCapture();
        }

        return true;
    }

    private bool TryGetPressedArcadeBinding(ArcadeBindingCaptureKind captureKind, out KeyCode binding)
    {
        Array allCodes = Enum.GetValues(typeof(KeyCode));
        for (int i = 0; i < allCodes.Length; i++)
        {
            KeyCode candidate = (KeyCode)allCodes.GetValue(i);
            if (candidate == KeyCode.None || !Input.GetKeyDown(candidate))
                continue;

            bool valid = captureKind == ArcadeBindingCaptureKind.Controller
                ? IsArcadeControllerBindingKeyCode(candidate)
                : IsArcadeKeyboardBindingKeyCode(candidate);
            if (!valid)
                continue;

            binding = NormalizeArcadeBinding(candidate);
            return true;
        }

        if (captureKind == ArcadeBindingCaptureKind.Controller)
        {
            RefreshSpecificControllerExtendedAxes();
            for (int slot = 1; slot <= ArcadeControllerSlotCount; slot++)
            {
                int slotIndex = slot - 1;
                if (previousSpecificControllerLeftTriggerAxes[slotIndex] < ControllerTriggerAxisPressThreshold &&
                    currentSpecificControllerLeftTriggerAxes[slotIndex] >= ControllerTriggerAxisPressThreshold)
                {
                    binding = KeyCode.JoystickButton6;
                    return true;
                }

                if (previousSpecificControllerRightTriggerAxes[slotIndex] < ControllerTriggerAxisPressThreshold &&
                    currentSpecificControllerRightTriggerAxes[slotIndex] >= ControllerTriggerAxisPressThreshold)
                {
                    binding = KeyCode.JoystickButton7;
                    return true;
                }
            }
        }

        binding = KeyCode.None;
        return false;
    }

    private static bool IsArcadeKeyboardBindingKeyCode(KeyCode code)
    {
        return code != KeyCode.None && !IsArcadeControllerBindingKeyCode(code) && !code.ToString().StartsWith("Mouse", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsArcadeControllerBindingKeyCode(KeyCode code)
    {
        string name = code.ToString();
        return name.StartsWith("JoystickButton", StringComparison.OrdinalIgnoreCase) ||
               Regex.IsMatch(name, @"^Joystick\d+Button\d+$", RegexOptions.CultureInvariant);
    }

    private static string SerializeHighwayCharacterDisplayMode(HighwayCharacterDisplayMode mode)
