    private void AddBackgroundMoodSection(List<RuntimeSettingSectionSnapshot> sections, string title, IEnumerable<string> settingIds)
    {
        if (sections == null || settingIds == null)
            return;

        List<RuntimeSettingSnapshot> settings = new List<RuntimeSettingSnapshot>();
        foreach (string settingId in settingIds)
        {
            if (string.IsNullOrWhiteSpace(settingId) || !runtimeSettingById.TryGetValue(settingId, out RuntimeSettingDefinition definition))
                continue;

            RuntimeSettingSnapshot snapshot = CreateRuntimeSettingSnapshot(definition);
            if (snapshot != null)
                settings.Add(snapshot);
        }

        if (settings.Count == 0)
            return;

        sections.Add(new RuntimeSettingSectionSnapshot
        {
            title = title,
            settings = settings
        });
    }

    private List<RuntimeSettingSnapshot> GetBackgroundMoodSetterItems()
    {
        return BuildBackgroundMoodSetterSections()
            .SelectMany(section => section?.settings ?? new List<RuntimeSettingSnapshot>())
            .Where(setting => setting != null)
            .ToList();
    }

    private void MoveBackgroundMoodSetterSelection(int delta)
    {
        List<RuntimeSettingSnapshot> settings = GetBackgroundMoodSetterItems();
        int totalOptions = settings.Count + 1;
        if (totalOptions <= 1)
        {
            selectedBackgroundMoodSettingIndex = -1;
            return;
        }

        int currentSlot = Mathf.Clamp(selectedBackgroundMoodSettingIndex + 1, 0, totalOptions - 1);
        int nextSlot = (currentSlot + delta + totalOptions) % totalOptions;
        selectedBackgroundMoodSettingIndex = nextSlot - 1;
    }

    private void ActivateCurrentBackgroundMoodSetting()
    {
        if (selectedBackgroundMoodSettingIndex < 0)
        {
            CloseBackgroundMoodSetterFromUi();
            return;
        }

        List<RuntimeSettingSnapshot> settings = GetBackgroundMoodSetterItems();
        if (settings.Count == 0)
            return;

        RuntimeSettingSnapshot setting = settings[Mathf.Clamp(selectedBackgroundMoodSettingIndex, 0, settings.Count - 1)];
        ActivateRuntimeSettingSnapshot(setting);
    }

    private void AdjustCurrentBackgroundMoodSetting(int delta)
    {
        if (delta == 0)
            return;

        if (selectedBackgroundMoodSettingIndex < 0)
            return;

        List<RuntimeSettingSnapshot> settings = GetBackgroundMoodSetterItems();
        if (settings.Count == 0)
            return;

        RuntimeSettingSnapshot setting = settings[Mathf.Clamp(selectedBackgroundMoodSettingIndex, 0, settings.Count - 1)];
        AdjustRuntimeSettingSnapshot(setting, delta);
    }

    private void ActivateRuntimeSettingSnapshot(RuntimeSettingSnapshot setting)
    {
        if (setting == null)
            return;

        if (runtimeSettingById.TryGetValue(setting.id, out RuntimeSettingDefinition definition) && definition.Activator != null &&
            (string.Equals(setting.valueType, "binding", StringComparison.OrdinalIgnoreCase) || string.Equals(setting.valueType, "action", StringComparison.OrdinalIgnoreCase)))
        {
            definition.Activator();
        }
        else if (string.Equals(setting.valueType, "bool", StringComparison.OrdinalIgnoreCase))
        {
            string nextValue = string.Equals(setting.value, "true", StringComparison.OrdinalIgnoreCase) ? "false" : "true";
            ApplyRuntimeSettingValue(setting.id, nextValue, saveMetadata: true);
        }
        else if (string.Equals(setting.valueType, "enum", StringComparison.OrdinalIgnoreCase) && setting.enumOptions != null && setting.enumOptions.Count > 0)
        {
            int currentIndex = setting.enumOptions.FindIndex(option => string.Equals(option, setting.value, StringComparison.OrdinalIgnoreCase));
            if (currentIndex < 0)
                currentIndex = 0;

            int nextIndex = (currentIndex + 1) % setting.enumOptions.Count;
            ApplyRuntimeSettingValue(setting.id, setting.enumOptions[nextIndex], saveMetadata: true);
        }
    }

    private void AdjustRuntimeSettingSnapshot(RuntimeSettingSnapshot setting, int delta)
    {
        if (setting == null ||
            string.Equals(setting.valueType, "binding", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(setting.valueType, "action", StringComparison.OrdinalIgnoreCase))
            return;

        if (string.Equals(setting.valueType, "bool", StringComparison.OrdinalIgnoreCase))
        {
            ApplyRuntimeSettingValue(setting.id, delta > 0 ? "true" : "false", saveMetadata: true);
            return;
        }

        if (string.Equals(setting.valueType, "enum", StringComparison.OrdinalIgnoreCase))
        {
            if (setting.enumOptions == null || setting.enumOptions.Count == 0)
                return;

            int currentIndex = setting.enumOptions.FindIndex(option => string.Equals(option, setting.value, StringComparison.OrdinalIgnoreCase));
            if (currentIndex < 0)
                currentIndex = 0;

            int nextIndex = (currentIndex + delta + setting.enumOptions.Count) % setting.enumOptions.Count;
            ApplyRuntimeSettingValue(setting.id, setting.enumOptions[nextIndex], saveMetadata: true);
            return;
        }

        if (!float.TryParse(setting.value, NumberStyles.Float, CultureInfo.InvariantCulture, out float currentValue))
            currentValue = setting.min;

        float step = Mathf.Abs(setting.step) > 0.0001f ? setting.step : 1f;
        float nextValue = Mathf.Clamp(currentValue + (delta * step), setting.min, setting.max);
        string serialized = string.Equals(setting.valueType, "int", StringComparison.OrdinalIgnoreCase)
            ? Mathf.RoundToInt(nextValue).ToString(CultureInfo.InvariantCulture)
            : nextValue.ToString("0.###", CultureInfo.InvariantCulture);
        ApplyRuntimeSettingValue(setting.id, serialized, saveMetadata: true);
    }

    private static string GetGlobalSettingsCategoryFromTopIndex(int index)
    {
        switch (index)
        {
            case 4: return "Audio";
            case 5: return "Gameplay";
            case 6: return "2D Tabs";
            case 7: return "Highway3D";
            case 8: return "Rhythm";
            case 9: return "Controls";
            case 10: return "Visuals";
            case 11: return "Multiplayer Visuals";
            case 12: return "Diagnostics";
            default: return string.Empty;
        }
    }

    private static string CategorizeRuntimeSettingsSectionForMenu(RuntimeSettingSectionSnapshot section)
    {
        string normalizedTitle = section?.title?.ToLowerInvariant() ?? string.Empty;
        List<RuntimeSettingSnapshot> sectionSettings = section?.settings;

        if (normalizedTitle.Contains("multiplayer") || IsRuntimeSettingsSectionIdPrefix(sectionSettings, "mp."))
            return "Multiplayer Visuals";

        if (normalizedTitle.Contains("audio") || IsRuntimeSettingsSectionIdPrefix(sectionSettings, "audio."))
            return "Audio";

        if (normalizedTitle.Contains("diagnostic") || IsRuntimeSettingsSectionIdPrefix(sectionSettings, "diagnostics."))
            return "Diagnostics";

        if (normalizedTitle.Contains("control") || IsRuntimeSettingsSectionIdPrefix(sectionSettings, "arcade.controls."))
            return "Controls";

        if (normalizedTitle.Contains("arcade") || IsRuntimeSettingsSectionIdPrefix(sectionSettings, "arcade."))
            return "Rhythm";

        if (normalizedTitle.Contains("timing") || normalizedTitle.Contains("forgiveness") || normalizedTitle.Contains("settings") || IsRuntimeSettingsSectionIdPrefix(sectionSettings, "core.") || IsRuntimeSettingsSectionIdPrefix(sectionSettings, "timing."))
            return "Gameplay";

        if (normalizedTitle.Contains("tab") || normalizedTitle.Contains("layout") || IsRuntimeSettingsSectionIdPrefix(sectionSettings, "layout."))
            return "2D Tabs";

        if (normalizedTitle.Contains("highway") || IsRuntimeSettingsSectionIdPrefix(sectionSettings, "highway.") || IsRuntimeSettingsSectionIdPrefix(sectionSettings, "render."))
            return "Highway3D";

        if (normalizedTitle.Contains("visual") || normalizedTitle.Contains("color") || normalizedTitle.Contains("background") || IsRuntimeSettingsSectionIdPrefix(sectionSettings, "fx.") || IsRuntimeSettingsSectionIdPrefix(sectionSettings, "bg."))
            return "Visuals";

        return "Gameplay";
    }

    private static bool IsRuntimeSettingsSectionIdPrefix(List<RuntimeSettingSnapshot> settings, string prefix)
    {
        if (settings == null || string.IsNullOrEmpty(prefix))
            return false;

        return settings.Any(setting =>
            setting != null &&
            !string.IsNullOrEmpty(setting.id) &&
            setting.id.StartsWith(prefix, StringComparison.OrdinalIgnoreCase));
    }

    private List<RuntimeSettingSectionSnapshot> BuildRuntimeSettingsSnapshot()
    {
        if (!runtimeSettingsSnapshotDirty && cachedRuntimeSettingsSnapshot != null)
            return cachedRuntimeSettingsSnapshot;

        cachedRuntimeSettingsSnapshot = runtimeSettingDefinitions
            .Where(def => def != null && def.VisibleInGlobalSettings)
            .GroupBy(def => def.Section)
            .Select(group => new RuntimeSettingSectionSnapshot
            {
                title = group.Key,
                settings = group.Select(CreateRuntimeSettingSnapshot).ToList()
            })
            .ToList();

        runtimeSettingsSnapshotDirty = false;
        return cachedRuntimeSettingsSnapshot;
    }

    private static RuntimeSettingSnapshot CreateRuntimeSettingSnapshot(RuntimeSettingDefinition definition)
    {
        if (definition == null)
            return null;

        return new RuntimeSettingSnapshot
        {
            id = definition.Id,
            label = definition.Label,
            tooltip = definition.Tooltip,
            valueType = definition.ValueType,
            value = definition.Getter != null ? definition.Getter() : string.Empty,
            min = definition.Min,
            max = definition.Max,
            step = definition.Step,
            enumOptions = definition.EnumOptions != null ? new List<string>(definition.EnumOptions) : new List<string>()
        };
    }

    private void ApplyRuntimeSettingValue(string settingId, string serializedValue, bool saveMetadata)
    {
        if (string.IsNullOrEmpty(settingId) || !runtimeSettingById.TryGetValue(settingId, out RuntimeSettingDefinition definition) || definition.Setter == null)
            return;

        definition.Setter(serializedValue ?? string.Empty);
        runtimeSettingsSnapshotDirty = true;
        RefreshRuntimeSettingVisuals(settingId);

        if (saveMetadata)
            SaveGlobalRuntimeSettingsMetadata();
    }

    private void RefreshRuntimeSettingVisuals(string settingId)
    {
        if (string.IsNullOrEmpty(settingId))
            return;

        bool requiresSectionRebuild = settingId.StartsWith("tabs.tabSection", StringComparison.OrdinalIgnoreCase);
        bool liveNeonHorizonSetting = settingId.StartsWith("bg.neonHorizon.", StringComparison.OrdinalIgnoreCase);
        bool requiresRendererRefresh =
            requiresSectionRebuild ||
            settingId.StartsWith("render.", StringComparison.OrdinalIgnoreCase) ||
            settingId.StartsWith("arcade.highway", StringComparison.OrdinalIgnoreCase) ||
            settingId.StartsWith("arcade.noteSpawn", StringComparison.OrdinalIgnoreCase) ||
            settingId.StartsWith("arcade.resolvedHold", StringComparison.OrdinalIgnoreCase) ||
            settingId.StartsWith("highway.", StringComparison.OrdinalIgnoreCase) ||
            (settingId.StartsWith("bg.", StringComparison.OrdinalIgnoreCase) && !liveNeonHorizonSetting) ||
            settingId.StartsWith("layout.", StringComparison.OrdinalIgnoreCase) ||
            settingId.StartsWith("fx.", StringComparison.OrdinalIgnoreCase);

        if (requiresSectionRebuild)
            GenerateTabSections();

        if (requiresRendererRefresh)
            ResetActiveRendererContent();
    }

    private bool NormalizeLegacyRhythmRuntimeSettings(Dictionary<string, string> values)
    {
        if (values == null || values.Count == 0)
            return false;

        bool changed = false;

        changed |= TryMigrateLegacyCharacterSettings(values);

        changed |= ReplaceTransientRuntimeBindingPromptWithDefault(values, "arcade.controls.controller.green");
        changed |= ReplaceTransientRuntimeBindingPromptWithDefault(values, "arcade.controls.controller.red");
        changed |= ReplaceTransientRuntimeBindingPromptWithDefault(values, "arcade.controls.controller.yellow");
        changed |= ReplaceTransientRuntimeBindingPromptWithDefault(values, "arcade.controls.controller.blue");
        changed |= ReplaceTransientRuntimeBindingPromptWithDefault(values, "arcade.controls.controller.orange");
        changed |= ReplaceTransientRuntimeBindingPromptWithDefault(values, "arcade.controls.controller.strumUp");
        changed |= ReplaceTransientRuntimeBindingPromptWithDefault(values, "arcade.controls.controller.strumDown");
        changed |= ReplaceTransientRuntimeBindingPromptWithDefault(values, "arcade.controls.controller.open");

        if (TryMigrateLegacyKeyboardStrumDefaults(values))
            changed = true;

        if (TryMigrateLegacyControllerDefaults(values))
            changed = true;

        return changed;
    }

    private static bool TryMigrateLegacyCharacterSettings(Dictionary<string, string> values)
    {
        if (values == null || !values.TryGetValue("fx.characterAnimationsEnabled", out string legacyValue))
            return false;

        bool changed = false;
        if (!values.ContainsKey("fx.characterMovementEnabled"))
        {
            values["fx.characterMovementEnabled"] = legacyValue ?? "true";
            changed = true;
        }

        if (!values.ContainsKey("fx.characterMissColorEnabled"))
        {
            values["fx.characterMissColorEnabled"] = legacyValue ?? "true";
            changed = true;
        }

        if (!values.ContainsKey("fx.characterMissParticlesEnabled"))
        {
            values["fx.characterMissParticlesEnabled"] = "false";
            changed = true;
        }

        if (values.Remove("fx.characterAnimationsEnabled"))
            changed = true;

        return changed;
    }

    private bool ReplaceTransientRuntimeBindingPromptWithDefault(Dictionary<string, string> values, string settingId)
    {
        if (values == null || string.IsNullOrEmpty(settingId) || !values.TryGetValue(settingId, out string value) || string.IsNullOrWhiteSpace(value))
            return false;

        if (!value.StartsWith("PRESS ", StringComparison.OrdinalIgnoreCase))
            return false;

        if (!runtimeSettingDefaultValues.TryGetValue(settingId, out string defaultValue))
            return false;

        values[settingId] = defaultValue ?? string.Empty;
        return true;
    }

    private static bool TryMigrateLegacyKeyboardStrumDefaults(Dictionary<string, string> values)
    {
        if (values == null)
            return false;

        bool matchesLegacyKeyboardDefaults =
            MatchesRuntimeSettingValue(values, "arcade.controls.keyboard.green", "A") &&
            MatchesRuntimeSettingValue(values, "arcade.controls.keyboard.red", "S") &&
            MatchesRuntimeSettingValue(values, "arcade.controls.keyboard.yellow", "J") &&
            MatchesRuntimeSettingValue(values, "arcade.controls.keyboard.blue", "K") &&
            MatchesRuntimeSettingValue(values, "arcade.controls.keyboard.orange", "L") &&
            MatchesRuntimeSettingValue(values, "arcade.controls.keyboard.strumUp", "UpArrow") &&
            MatchesRuntimeSettingValue(values, "arcade.controls.keyboard.strumDown", "DownArrow") &&
            MatchesRuntimeSettingValue(values, "arcade.controls.keyboard.open", "None");

        if (!matchesLegacyKeyboardDefaults)
            return false;

        values["arcade.controls.keyboard.strumUp"] = KeyCode.Space.ToString();
        values["arcade.controls.keyboard.strumDown"] = KeyCode.None.ToString();
        return true;
    }

    private static bool TryMigrateLegacyControllerDefaults(Dictionary<string, string> values)
    {
        if (values == null)
            return false;

        bool legacyPadLayout =
            (MatchesRuntimeSettingValue(values, "arcade.controls.controller.green", "JoystickButton0") ||
             MatchesRuntimeSettingValue(values, "arcade.controls.controller.green", "JoystickButton6")) &&
            MatchesRuntimeSettingValue(values, "arcade.controls.controller.red", "JoystickButton1") &&
            MatchesRuntimeSettingValue(values, "arcade.controls.controller.yellow", "JoystickButton2") &&
            MatchesRuntimeSettingValue(values, "arcade.controls.controller.blue", "JoystickButton3") &&
            MatchesRuntimeSettingValue(values, "arcade.controls.controller.orange", "JoystickButton4") &&
            MatchesRuntimeSettingValue(values, "arcade.controls.controller.strumUp", "JoystickButton5") &&
            MatchesRuntimeSettingValue(values, "arcade.controls.controller.strumDown", "JoystickButton6") &&
            MatchesRuntimeSettingValue(values, "arcade.controls.controller.open", "JoystickButton8");

        if (!legacyPadLayout)
            return false;

        values["arcade.controls.controller.green"] = KeyCode.JoystickButton6.ToString();
        values["arcade.controls.controller.red"] = KeyCode.JoystickButton4.ToString();
        values["arcade.controls.controller.yellow"] = KeyCode.JoystickButton5.ToString();
        values["arcade.controls.controller.blue"] = KeyCode.JoystickButton7.ToString();
        values["arcade.controls.controller.orange"] = KeyCode.JoystickButton0.ToString();
        values["arcade.controls.controller.strumUp"] = KeyCode.JoystickButton13.ToString();
        values["arcade.controls.controller.strumDown"] = KeyCode.JoystickButton14.ToString();
        return true;
    }

    private static bool MatchesRuntimeSettingValue(Dictionary<string, string> values, string settingId, string expectedValue)
    {
        return values.TryGetValue(settingId, out string currentValue) &&
               string.Equals(currentValue ?? string.Empty, expectedValue ?? string.Empty, StringComparison.OrdinalIgnoreCase);
    }

    private static bool RuntimeSettingFloatLooksLike(Dictionary<string, string> values, string settingId, float expectedValue)
    {
        if (values == null || !values.TryGetValue(settingId, out string currentValue))
            return false;

        return float.TryParse(currentValue, NumberStyles.Float, CultureInfo.InvariantCulture, out float parsedValue) &&
               Mathf.Abs(parsedValue - expectedValue) <= 0.0001f;
    }

    private static bool ApplyGlobalRuntimeSettingsMigrations(Dictionary<string, string> values, int sourceVersion, out int migratedVersion)
    {
        migratedVersion = Mathf.Max(0, sourceVersion);
        if (values == null)
            return false;

        bool migrated = false;

        if (migratedVersion < 1)
        {
            SetRuntimeSettingMigrationValue(values, "bg.skyStarCount", "500");
            SetRuntimeSettingMigrationValue(values, "highway.showHitNoteFeedbackBox", "false");
            SetRuntimeSettingMigrationValue(values, "highway.showMissNoteFeedbackBox", "false");
            migratedVersion = 1;
            migrated = true;
        }

        if (migratedVersion < 2)
        {
            if (!values.ContainsKey("timing.hitWindowLate") ||
                RuntimeSettingFloatLooksLike(values, "timing.hitWindowLate", 0.35f) ||
                RuntimeSettingFloatLooksLike(values, "timing.hitWindowLate", 0.5f))
            {
                SetRuntimeSettingMigrationValue(values, "timing.hitWindowLate", "0.25");
                migrated = true;
            }

            if (values.Remove("timing.judgmentGrace"))
                migrated = true;

            migratedVersion = 2;
        }

        if (migratedVersion < 3)
        {
            SetRuntimeSettingMigrationValue(values, "fx.characterRigOffsetX", "-0.025");
            SetRuntimeSettingMigrationValue(values, "fx.characterRigOffsetY", "0.005");
            SetRuntimeSettingMigrationValue(values, "fx.characterOffsetX", "0.03");
            SetRuntimeSettingMigrationValue(values, "fx.characterOffsetY", "0.045");
            SetRuntimeSettingMigrationValue(values, "highway.spawnZ", "180");
            migratedVersion = 3;
            migrated = true;
        }

        if (migratedVersion < 4)
        {
            SetRuntimeSettingMigrationValue(values, "highway.showMissFretFeedback", "false");
            migratedVersion = 4;
            migrated = true;
        }

        if (migratedVersion < 5)
        {
            SetRuntimeSettingMigrationValue(values, "highway.showHitNoteFeedbackBox", "true");
            SetRuntimeSettingMigrationValue(values, "highway.showMissNoteFeedbackBox", "true");
            migratedVersion = 5;
            migrated = true;
        }

        if (migratedVersion < 6)
        {
            SetRuntimeSettingMigrationValue(values, "highway.cameraEngine", "Smart Lookahead");
            SetRuntimeSettingMigrationValue(values, "fx.characterRigOffsetX", "-0.025");
            SetRuntimeSettingMigrationValue(values, "fx.characterRigOffsetY", "0.005");
            SetRuntimeSettingMigrationValue(values, "fx.characterOffsetX", "0.03");
            SetRuntimeSettingMigrationValue(values, "fx.characterOffsetY", "0.045");
            migratedVersion = 6;
            migrated = true;
        }

        if (migratedVersion < 7)
        {
            if (!values.ContainsKey("bg.neonHorizon.enviroGroundMode"))
            {
                bool legacyGroundEnabled = MatchesRuntimeSettingValue(values, "bg.neonHorizon.enviroGround", "true");
                SetRuntimeSettingMigrationValue(values, "bg.neonHorizon.enviroGroundMode", legacyGroundEnabled ? "Flat Plane" : "Off");
                migrated = true;
            }

            migratedVersion = 7;
        }

        if (migratedVersion < 8)
        {
            string legacyGroundModeValue = null;
            if (!values.TryGetValue("bg.neonHorizon.enviroGroundMode", out legacyGroundModeValue) || string.IsNullOrWhiteSpace(legacyGroundModeValue))
            {
                bool legacyGroundEnabled = MatchesRuntimeSettingValue(values, "bg.neonHorizon.enviroGround", "true");
                legacyGroundModeValue = legacyGroundEnabled ? "Flat Plane" : "Off";
            }

            if (!values.TryGetValue("bg.neonHorizon.enviroMood", out string enviroMoodValue))
                enviroMoodValue = null;

            int currentMoodIndex = ParseIndexedOption(EnviroSkyMoodOptions, enviroMoodValue, 0);
            string normalizedLegacyGroundMode = GetIndexedOption(EnviroGroundModeOptions, ParseEnviroGroundModeOption(legacyGroundModeValue, 0));

            for (int i = 0; i < EnviroSkyMoodOptions.Length; i++)
            {
                string groundSettingId = GetEnviroMoodSettingId(i, "groundMode");
                if (!values.ContainsKey(groundSettingId))
                {
                    SetRuntimeSettingMigrationValue(values, groundSettingId, i == currentMoodIndex ? normalizedLegacyGroundMode : "Off");
                    migrated = true;
                }

                string opacitySettingId = GetEnviroMoodSettingId(i, "mountainOpacity");
                if (!values.ContainsKey(opacitySettingId))
                {
                    SetRuntimeSettingMigrationValue(values, opacitySettingId, "1");
                    migrated = true;
                }
            }

            migratedVersion = 8;
        }

        if (migratedVersion < 9)
        {
            for (int i = 0; i < EnviroSkyMoodOptions.Length; i++)
            {
                string legacyOpacityId = GetEnviroMoodSettingId(i, "mountainOpacity");
                float legacyOpacity = 1f;
                if (values.TryGetValue(legacyOpacityId, out string legacyOpacityValue) &&
                    float.TryParse(legacyOpacityValue, NumberStyles.Float, CultureInfo.InvariantCulture, out float parsedOpacity))
                {
                    legacyOpacity = Mathf.Clamp01(parsedOpacity);
                }

                string farOpacityId = GetEnviroMoodSettingId(i, "mountainOpacityFar");
                if (!values.ContainsKey(farOpacityId))
                {
                    SetRuntimeSettingMigrationValue(values, farOpacityId, (GetDefaultEnviroMountainLayerOpacity(0) * legacyOpacity).ToString("0.###", CultureInfo.InvariantCulture));
                    migrated = true;
                }

                string midOpacityId = GetEnviroMoodSettingId(i, "mountainOpacityMid");
                if (!values.ContainsKey(midOpacityId))
                {
                    SetRuntimeSettingMigrationValue(values, midOpacityId, (GetDefaultEnviroMountainLayerOpacity(1) * legacyOpacity).ToString("0.###", CultureInfo.InvariantCulture));
                    migrated = true;
                }

                string nearOpacityId = GetEnviroMoodSettingId(i, "mountainOpacityNear");
                if (!values.ContainsKey(nearOpacityId))
                {
                    SetRuntimeSettingMigrationValue(values, nearOpacityId, (GetDefaultEnviroMountainLayerOpacity(2) * legacyOpacity).ToString("0.###", CultureInfo.InvariantCulture));
                    migrated = true;
                }
            }

            migratedVersion = 9;
        }

        if (migratedVersion < 10)
        {
            for (int i = 0; i < EnviroSkyMoodOptions.Length; i++)
            {
                string skyCameraPitchId = GetEnviroMoodSettingId(i, "skyCameraPitch");
                if (!values.ContainsKey(skyCameraPitchId))
                {
                    SetRuntimeSettingMigrationValue(values, skyCameraPitchId, "0");
                    migrated = true;
                }
            }

            migratedVersion = 10;
        }

        if (migratedVersion < 12)
        {
            for (int i = 0; i < EnviroSkyMoodOptions.Length; i++)
            {
                string starAnimationId = GetEnviroMoodSettingId(i, "starAnimation");
                if (!values.ContainsKey(starAnimationId))
                {
                    SetRuntimeSettingMigrationValue(values, starAnimationId, "1");
                    migrated = true;
                }
            }

            migratedVersion = 12;
        }

        if (migratedVersion < 13)
        {
            for (int i = 0; i < EnviroSkyMoodOptions.Length; i++)
            {
                string starDensityId = GetEnviroMoodSettingId(i, "starDensity");
                if (!values.ContainsKey(starDensityId))
                {
                    SetRuntimeSettingMigrationValue(values, starDensityId, "1");
                    migrated = true;
                }
            }

            migratedVersion = 13;
        }

        return migrated;
    }

    private static void SetRuntimeSettingMigrationValue(Dictionary<string, string> values, string settingId, string value)
    {
        if (values == null || string.IsNullOrEmpty(settingId))
            return;

        values[settingId] = value ?? string.Empty;
    }

    private static bool IsSharedAudioRuntimeSettingId(string settingId)
    {
        return !string.IsNullOrWhiteSpace(settingId) &&
               settingId.StartsWith("audio.", StringComparison.OrdinalIgnoreCase);
    }

    private void LoadGlobalRuntimeSettingsMetadata()
    {
        pendingGlobalRuntimeSettingValues.Clear();
        loadedGlobalRuntimeSettingsVersion = CurrentGlobalRuntimeSettingsVersion;
        selectedHighwayCharacter = HighwayCharacterChoice.Hero;
        selectedCharacterSelectionIndex = GetCurrentCharacterSelectionIndex();
        string path = Path.Combine(ExternalContentPaths.PersistentRoot, GlobalRuntimeSettingsFileName);

        try
        {
            Directory.CreateDirectory(Path.GetDirectoryName(path));
            if (!File.Exists(path))
            {
                ApplyDefaultRuntimeSettings();
                SaveGlobalRuntimeSettingsMetadata();
                return;
            }

            string json = File.ReadAllText(path);
            GlobalRuntimeSettingsMetadata metadata = JsonUtility.FromJson<GlobalRuntimeSettingsMetadata>(json);
            loadedGlobalRuntimeSettingsVersion = Mathf.Max(0, metadata?.settingsVersion ?? 0);
            selectedHighwayCharacter = ParseHighwayCharacterChoice(metadata?.selectedHighwayCharacterId);
            selectedCharacterSelectionIndex = GetCurrentCharacterSelectionIndex();
            mainMenuBackgroundProfile = metadata?.mainMenuBackgroundProfile ?? new MainMenuBackgroundProfile();
            MainMenuBackground.Ensure();

            List<RuntimeSettingValueEntry> metadataValues = metadata?.values ?? new List<RuntimeSettingValueEntry>();
            foreach (RuntimeSettingValueEntry entry in metadataValues)
            {
                if (entry == null || string.IsNullOrEmpty(entry.id))
                    continue;

                if (IsSharedAudioRuntimeSettingId(entry.id))
                    continue;

                pendingGlobalRuntimeSettingValues[entry.id] = entry.value ?? string.Empty;
            }

            bool normalizedLegacyBindings = NormalizeLegacyRhythmRuntimeSettings(pendingGlobalRuntimeSettingValues);
            bool appliedRuntimeSettingsMigrations = ApplyGlobalRuntimeSettingsMigrations(
                pendingGlobalRuntimeSettingValues,
                loadedGlobalRuntimeSettingsVersion,
                out loadedGlobalRuntimeSettingsVersion);

            foreach (KeyValuePair<string, string> pair in pendingGlobalRuntimeSettingValues)
                ApplyRuntimeSettingValue(pair.Key, pair.Value, saveMetadata: false);

            Dictionary<string, string> defaults = LoadRuntimeSettingDefaultsFromFile();
            bool appliedMissingDefaults = false;

            foreach (RuntimeSettingDefinition definition in runtimeSettingDefinitions)
            {
                if (definition == null || string.IsNullOrEmpty(definition.Id))
                    continue;

                if (IsSharedAudioRuntimeSettingId(definition.Id))
                    continue;

                if (pendingGlobalRuntimeSettingValues.ContainsKey(definition.Id))
                    continue;

                string value;
                if (!defaults.TryGetValue(definition.Id, out value) && !runtimeSettingDefaultValues.TryGetValue(definition.Id, out value))
                    continue;

                ApplyRuntimeSettingValue(definition.Id, value, saveMetadata: false);
                pendingGlobalRuntimeSettingValues[definition.Id] = value;
                appliedMissingDefaults = true;
            }

            selectedCharacterSelectionIndex = GetCurrentCharacterSelectionIndex();

            if (appliedMissingDefaults || normalizedLegacyBindings || appliedRuntimeSettingsMigrations)
                SaveGlobalRuntimeSettingsMetadata();
        }
        catch (Exception ex)
        {
            Debug.LogWarning($"Failed to load global settings metadata: {ex.Message}");
        }
    }

    private void SaveGlobalRuntimeSettingsMetadata()
    {
        string path = Path.Combine(ExternalContentPaths.PersistentRoot, GlobalRuntimeSettingsFileName);

        try
        {
            Directory.CreateDirectory(Path.GetDirectoryName(path));
            int versionToSave = Mathf.Max(loadedGlobalRuntimeSettingsVersion, CurrentGlobalRuntimeSettingsVersion);
            savingRuntimeSettingsMetadata = true;
            List<RuntimeSettingValueEntry> values;
            try
            {
                values = runtimeSettingDefinitions
                    .Where(def => def != null && !IsSharedAudioRuntimeSettingId(def.Id))
                    .Select(def => new RuntimeSettingValueEntry
                    {
                        id = def.Id,
                        value = def.Getter != null ? def.Getter() : string.Empty
                    })
                    .ToList();
            }
            finally
            {
                savingRuntimeSettingsMetadata = false;
            }

            GlobalRuntimeSettingsMetadata metadata = new GlobalRuntimeSettingsMetadata
            {
                settingsVersion = versionToSave,
                selectedHighwayCharacterId = SerializeHighwayCharacterChoice(selectedHighwayCharacter),
                mainMenuBackgroundProfile = MainMenuBackground,
                values = values
            };

            File.WriteAllText(path, JsonUtility.ToJson(metadata, true));
            loadedGlobalRuntimeSettingsVersion = versionToSave;
        }
        catch (Exception ex)
        {
            Debug.LogWarning($"Failed to save global settings metadata: {ex.Message}");
        }
    }

    private void ApplyDefaultRuntimeSettings()
    {
        Dictionary<string, string> defaults = LoadRuntimeSettingDefaultsFromFile();

        foreach (RuntimeSettingDefinition definition in runtimeSettingDefinitions)
        {
            if (definition == null || string.IsNullOrEmpty(definition.Id))
                continue;

            string value;
            if (!defaults.TryGetValue(definition.Id, out value) && !runtimeSettingDefaultValues.TryGetValue(definition.Id, out value))
                continue;

            ApplyRuntimeSettingValue(definition.Id, value, saveMetadata: false);
        }
    }

    private static Dictionary<string, string> LoadRuntimeSettingDefaultsFromFile()
    {
        Dictionary<string, string> result = new Dictionary<string, string>();
        string path = Path.Combine(ExternalContentPaths.StreamingRoot, "runtime_settings_defaults.json");

        try
        {
            if (!File.Exists(path))
                return result;

            string json = File.ReadAllText(path);
            GlobalRuntimeSettingsMetadata metadata = JsonUtility.FromJson<GlobalRuntimeSettingsMetadata>(json);
            if (metadata?.values == null)
                return result;

            foreach (RuntimeSettingValueEntry entry in metadata.values)
            {
                if (entry == null || string.IsNullOrEmpty(entry.id))
                    continue;

                result[entry.id] = entry.value ?? string.Empty;
            }
        }
        catch (Exception ex)
        {
            Debug.LogWarning($"Failed to load runtime setting defaults: {ex.Message}");
        }

        return result;
    }

    private void ApplyPlaybackSpeedToAudio()
    {
        float speed = GetPlaybackSpeedScale();
        float volume = Mathf.Clamp01(songVolumePercent / 100f);
        generatedSongPlayer?.SetMasterVolumePercent(songVolumePercent);

        if (backingTrackSource == null)
            return;

        if (!Mathf.Approximately(backingTrackSource.pitch, speed))
            backingTrackSource.pitch = speed;

        if (!Mathf.Approximately(backingTrackSource.volume, volume))
            backingTrackSource.volume = volume;

        if (currentStemPlaybackActive)
        {
            ApplyStemSmartDucking();
            for (int i = 0; i < stemAudioSources.Count; i++)
            {
                StemAudioSourceState state = stemAudioSources[i];
                AudioSource source = state?.source;
                if (source == null || source.clip == null)
                    continue;

                if (!Mathf.Approximately(source.pitch, speed))
                    source.pitch = speed;

                float stemVolume = volume * Mathf.Clamp01(GetStemMixerVolumePercent(state.stemId) / 100f);
                if (IsSmartDuckedStem(state.stemId))
                    stemVolume *= stemSmartDuckCurrentMultiplier;

                if (!Mathf.Approximately(source.volume, stemVolume))
                    source.volume = stemVolume;
            }
        }

        if (gameplayMode == GuitarGameplayMode.Arcade && arcadeAudioSources != null)
        {
            for (int i = 0; i < arcadeAudioSources.Count; i++)
            {
                AudioSource source = arcadeAudioSources[i];
                if (source == null || source == backingTrackSource)
                    continue;

                if (!Mathf.Approximately(source.pitch, speed))
                    source.pitch = speed;
                if (!Mathf.Approximately(source.volume, volume))
                    source.volume = volume;
            }
        }
    }

    private void ApplyStemSmartDucking()
    {
        if (!stemSmartDuckingEnabled || !currentStemPlaybackActive || chartNotes == null || chartNotes.Count == 0)
        {
            stemSmartDuckCurrentMultiplier = Mathf.MoveTowards(stemSmartDuckCurrentMultiplier, 1f, Time.deltaTime * 4.5f);
            return;
        }

        float audibleTimelineTime = audioSongTimer + (audioOffsetMs / 1000f);
        bool active = IsSelectedChartActiveNearTime(audibleTimelineTime);
        float target = active ? Mathf.Clamp01(1f - DefaultStemSmartDuckingStrengthPercent / 100f) : 1f;
        float speed = active ? 12f : 4.5f;
        stemSmartDuckCurrentMultiplier = Mathf.MoveTowards(stemSmartDuckCurrentMultiplier, target, Time.deltaTime * speed);
    }

    private bool IsSmartDuckedStem(string stemId)
    {
        if (!stemSmartDuckingEnabled || string.IsNullOrWhiteSpace(stemId))
            return false;

        MusicXmlLoader.MusicXmlPartSummary summary = GetResolvedActiveTrackSummary();
        bool bassTrack = IsBassLikeTrackSummary(summary);
        if (bassTrack)
            return string.Equals(stemId, "bass", StringComparison.OrdinalIgnoreCase);

        return string.Equals(stemId, "guitar", StringComparison.OrdinalIgnoreCase) ||
               string.Equals(stemId, "other", StringComparison.OrdinalIgnoreCase);
    }

    private bool IsSelectedChartActiveNearTime(float timeSeconds)
    {
        const float PreRollSeconds = 0.035f;
        const float ReleaseSeconds = 0.11f;
        for (int i = 0; i < chartNotes.Count; i++)
        {
            NoteData note = chartNotes[i];
            float start = note.time - PreRollSeconds;
            if (start > timeSeconds)
                continue;

            float end = note.time + Mathf.Max(0.05f, note.duration) + ReleaseSeconds;
            if (timeSeconds <= end)
                return true;
        }

        return false;
    }

    private void SyncAudioToSongTimer(bool playImmediately, bool forceSeek = false)
    {
        SongPlaybackAudioMode effectiveMode = GetEffectiveSongPlaybackAudioMode();
        float playbackSpeedScale = GetPlaybackSpeedScale();

        if (effectiveMode == SongPlaybackAudioMode.Generated)
        {
            if (backingTrackSource != null && backingTrackSource.isPlaying)
                backingTrackSource.Pause();
            PauseStemAudioSources(skipPrimary: true);
            PauseArcadeAudioSources(skipPrimary: true);

            generatedSongPlayer?.SyncTransport(audioSongTimer, playbackSpeedScale, playImmediately, forceSeek);
            return;
        }

        generatedSongPlayer?.SyncTransport(audioSongTimer, playbackSpeedScale, false, forceSeek);

        if (effectiveMode == SongPlaybackAudioMode.Muted)
        {
            if (backingTrackSource != null && backingTrackSource.isPlaying)
                backingTrackSource.Pause();
            PauseStemAudioSources(skipPrimary: true);
            PauseArcadeAudioSources(skipPrimary: true);
            return;
        }

        if (backingTrackSource == null || backingTrackSource.clip == null)
            return;

        float timelineAudioTime = audioSongTimer + (audioOffsetMs / 1000f);
        float audioTime = Mathf.Clamp(timelineAudioTime, 0f, backingTrackSource.clip.length);

        if (forceSeek || Mathf.Abs(backingTrackSource.time - audioTime) > 0.04f)
            backingTrackSource.time = audioTime;

        bool shouldBeSilentForCountdown = timelineAudioTime <= 0f;
        if (shouldBeSilentForCountdown)
        {
            if (backingTrackSource.isPlaying)
                backingTrackSource.Pause();
            PauseStemAudioSources(skipPrimary: true);
            return;
        }

        if (playImmediately)
        {
            if (!backingTrackSource.isPlaying && audioTime < backingTrackSource.clip.length)
                backingTrackSource.Play();
        }
        else if (backingTrackSource.isPlaying)
        {
            backingTrackSource.Pause();
        }

        if (gameplayMode == GuitarGameplayMode.Arcade)
            SyncArcadeAudioSources(timelineAudioTime, playImmediately, forceSeek);
        else if (currentStemPlaybackActive)
            SyncStemAudioSources(timelineAudioTime, playImmediately, forceSeek);
    }

    private void SyncStemAudioSources(float timelineAudioTime, bool playImmediately, bool forceSeek)
    {
        if (stemAudioSources == null || stemAudioSources.Count <= 1)
            return;

        bool shouldBeSilentForCountdown = timelineAudioTime <= 0f;
        for (int i = 1; i < stemAudioSources.Count; i++)
        {
            AudioSource source = stemAudioSources[i]?.source;
            if (source == null || source.clip == null)
                continue;

            float audioTime = Mathf.Clamp(timelineAudioTime, 0f, source.clip.length);
            if (forceSeek || Mathf.Abs(source.time - audioTime) > 0.04f)
                source.time = audioTime;

            if (shouldBeSilentForCountdown || !playImmediately)
            {
                if (source.isPlaying)
                    source.Pause();
                continue;
            }

            if (!source.isPlaying && audioTime < source.clip.length)
                source.Play();
        }
    }

    private void PauseStemAudioSources(bool skipPrimary)
    {
        if (stemAudioSources == null)
            return;

        for (int i = skipPrimary ? 1 : 0; i < stemAudioSources.Count; i++)
        {
            AudioSource source = stemAudioSources[i]?.source;
            if (source != null && source.isPlaying)
                source.Pause();
        }
    }

    private void SyncArcadeAudioSources(float timelineAudioTime, bool playImmediately, bool forceSeek)
    {
        if (arcadeAudioSources == null || arcadeAudioSources.Count <= 1)
            return;

        bool shouldBeSilentForCountdown = timelineAudioTime <= 0f;
        for (int i = 1; i < arcadeAudioSources.Count; i++)
        {
            AudioSource source = arcadeAudioSources[i];
            if (source == null || source.clip == null)
                continue;

            float audioTime = Mathf.Clamp(timelineAudioTime, 0f, source.clip.length);
            if (forceSeek || Mathf.Abs(source.time - audioTime) > 0.04f)
                source.time = audioTime;

            if (shouldBeSilentForCountdown || !playImmediately)
            {
                if (source.isPlaying)
                    source.Pause();
                continue;
            }

            if (!source.isPlaying && audioTime < source.clip.length)
                source.Play();
        }
    }

    private void PauseArcadeAudioSources(bool skipPrimary)
    {
        if (arcadeAudioSources == null)
            return;

        for (int i = skipPrimary ? 1 : 0; i < arcadeAudioSources.Count; i++)
        {
            AudioSource source = arcadeAudioSources[i];
            if (source != null && source.isPlaying)
                source.Pause();
        }
    }

    private List<NoteData> BuildDemoSong()
    {
        List<NoteData> demo = new List<NoteData>();
        float t = 2.0f;
        int idCounter = 0;

        Action<float, int, int, string> addNote = (time, str, fret, note) => {
            demo.Add(new NoteData { id = idCounter++, time = time, duration = 0, stringIdx = str, fret = fret, note = note });
        };

        // --- Block 1: High E (String 5) - Slow spacing ---
        addNote(t, 5, 0, "E4"); t += 1.0f;
        addNote(t, 5, 0, "E4"); t += 1.0f;
        addNote(t, 5, 0, "E4"); t += 1.0f;

        // --- Block 2: High E (String 5) - Fast picking ---
        addNote(t, 5, 0, "E4"); t += 0.25f;
        addNote(t, 5, 0, "E4"); t += 0.25f;
        addNote(t, 5, 0, "E4"); t += 0.25f;
        addNote(t, 5, 0, "E4"); t += 0.25f;
        addNote(t, 5, 0, "E4"); t += 1.5f;

        // --- Block 3: Low E (String 0) and High B (String 4) mix ---
        addNote(t, 0, 0, "E2"); t += 1.0f;
        addNote(t, 4, 0, "B3"); t += 1.0f;
        addNote(t, 0, 0, "E2"); t += 0.5f;
        addNote(t, 4, 0, "B3"); t += 0.5f;
        addNote(t, 0, 0, "E2"); t += 0.5f;
        addNote(t, 4, 0, "B3"); t += 1.5f;

        // --- Block 4: Open Chords ---
        
        // 3-String Open Chord: G, B, High E (Strings 3, 4, 5)
        addNote(t, 3, 0, "G3");
        addNote(t, 4, 0, "B3");
        addNote(t, 5, 0, "E4"); t += 1.5f;

        // 5-String Open Chord: Low E, D, G, B, High E (Skipping the A string)
        addNote(t, 0, 0, "E2");
        addNote(t, 2, 0, "D3");
        addNote(t, 3, 0, "G3");
        addNote(t, 4, 0, "B3");
        addNote(t, 5, 0, "E4"); t += 1.5f;

        // Full 6-String Open E Minor Chord
        addNote(t, 0, 0, "E2");
        addNote(t, 1, 2, "B2");
        addNote(t, 2, 2, "E3");
        addNote(t, 3, 0, "G3");
        addNote(t, 4, 0, "B3");
        addNote(t, 5, 0, "E4"); t += 2.0f;

        return demo;
    }

    private void GenerateTabSections()
    {
        tabSections = new List<TabSectionData>();
        if (chartNotes == null || chartNotes.Count == 0)
        {
            RefreshSongTimelineSections();
            return;
        }

        float maxTime = chartNotes.Max(n => n.time + n.duration);
        float sectionDuration = GetEffectiveTabSectionDuration();
        int totalSections = Mathf.Max(2, Mathf.CeilToInt(maxTime / sectionDuration) + 1);

        for (int i = 0; i < totalSections; i++)
        {
            float start = i * sectionDuration;
            float end = start + sectionDuration;

            var ids = chartNotes
                .Where(n => n.time >= start && n.time < end)
                .Select(n => n.id)
                .ToList();

            tabSections.Add(new TabSectionData
            {
                index = i,
                startTime = start,
                endTime = end,
                noteIds = ids
            });
        }

        RefreshSongTimelineSections();
    }

    private void RefreshSongTimelineSections()
    {
        songTimelineSections = new List<SongTimelineSectionData>();
        float duration = GetSongDurationSeconds();

        if (gameplayMode == GuitarGameplayMode.Arcade)
        {
            AddArcadeTimelineSections(duration);
        }
        else if (TryGetCurrentArrangementTimelineSections(out List<RocksmithCachedSectionData> arrangementSections, out float arrangementDuration) &&
                 arrangementSections != null &&
                 arrangementSections.Count > 0)
        {
            AddArrangementTimelineSections(arrangementSections, Mathf.Max(duration, arrangementDuration));
        }
        else if (currentSongEntry != null && currentSongEntry.PrimaryNotationKind == SongNotationSourceKind.Gp5)
        {
            AddGp5TimelineSections(duration);
        }

        if (songTimelineSections.Count == 0)
            AddGeneratedTimelineSections(duration);

        NormalizeTimelineSectionEnds(Mathf.Max(duration, GetTimelineLastEndTime()));
    }

    private bool TryGetCurrentArrangementTimelineSections(out List<RocksmithCachedSectionData> sections, out float duration)
    {
        sections = null;
        duration = 0f;
        if (currentSongEntry == null ||
            currentSongEntry.PrimaryNotationKind != SongNotationSourceKind.ArrangementCache ||
            string.IsNullOrWhiteSpace(currentSongEntry.PrimaryNotationPath))
        {
            return false;
        }

        if (TryGetCurrentArrangementCachePart(out RocksmithCachedArrangementPart selectedPart) &&
            selectedPart?.timing?.sections != null &&
            selectedPart.timing.sections.Count > 0)
        {
            sections = selectedPart.timing.sections;
            duration = selectedPart.durationSeconds;
            return true;
        }

        if (!RocksmithCachedSongLoader.TryLoadManifest(currentSongEntry.PrimaryNotationPath, out RocksmithCachedSongManifest manifest) ||
            manifest?.arrangements == null)
        {
            return false;
        }

        for (int i = 0; i < manifest.arrangements.Count; i++)
        {
            if (!RocksmithCachedSongLoader.TryLoadArrangementPart(currentSongEntry.PrimaryNotationPath, i, out _, out RocksmithCachedArrangementPart candidate) ||
                candidate?.timing?.sections == null ||
                candidate.timing.sections.Count == 0)
            {
                continue;
            }

            sections = candidate.timing.sections;
            duration = Mathf.Max(candidate.durationSeconds, manifest.durationSeconds);
            return true;
        }

        return false;
    }

    private struct Gp5TimelineTempoPoint
    {
        public double quarterPos;
        public double bpm;
    }

    private void AddGp5TimelineSections(float duration)
    {
        if (currentSongEntry == null ||
            currentSongEntry.PrimaryNotationKind != SongNotationSourceKind.Gp5 ||
            string.IsNullOrWhiteSpace(currentSongEntry.PrimaryNotationPath))
        {
            return;
        }

        Gp5Song song = Gp5Loader.GetParsedSong(currentSongEntry.PrimaryNotationPath);
        if (song?.measureHeaders == null || song.measureHeaders.Count == 0)
            return;

        List<Gp5TimelineTempoPoint> tempoMap = BuildGp5TimelineTempoMap(song);
        int index = 0;
        float lastStartTime = -1f;
        foreach (Gp5MeasureHeader header in song.measureHeaders.OrderBy(header => header.startQuarter))
        {
            if (header == null || string.IsNullOrWhiteSpace(header.markerName))
                continue;

            float startTime = Mathf.Max(0f, (float)Gp5QuarterToSeconds(header.startQuarter, tempoMap));
            if (startTime > duration + 2f)
                continue;

            if (songTimelineSections.Count > 0 && Mathf.Abs(lastStartTime - startTime) <= 0.001f)
            {
                songTimelineSections[songTimelineSections.Count - 1].name = FormatTimelineSectionName(header.markerName, index);
                continue;
            }

            songTimelineSections.Add(new SongTimelineSectionData
            {
                index = index,
                name = FormatTimelineSectionName(header.markerName, index),
                startTime = startTime,
                endTime = Mathf.Max(startTime + 0.05f, duration)
            });
            index++;
            lastStartTime = startTime;
        }
    }

    private static List<Gp5TimelineTempoPoint> BuildGp5TimelineTempoMap(Gp5Song song)
    {
        List<Gp5TimelineTempoPoint> tempoMap = new List<Gp5TimelineTempoPoint>();
        if (song?.tempoChanges != null)
        {
            for (int i = 0; i < song.tempoChanges.Count; i++)
            {
                Gp5TempoChange change = song.tempoChanges[i];
                if (change == null)
                    continue;

                tempoMap.Add(new Gp5TimelineTempoPoint
                {
                    quarterPos = Math.Max(0.0, change.quarterPos),
                    bpm = Math.Max(1.0, change.bpm)
                });
            }
        }

        tempoMap = tempoMap
            .OrderBy(point => point.quarterPos)
            .ToList();

        if (tempoMap.Count == 0 || tempoMap[0].quarterPos > 0.0001)
        {
            tempoMap.Insert(0, new Gp5TimelineTempoPoint
            {
                quarterPos = 0.0,
                bpm = Math.Max(1.0, song != null ? song.initialTempo : 120)
            });
        }

        return tempoMap;
    }

    private static double Gp5QuarterToSeconds(double quarterPos, List<Gp5TimelineTempoPoint> tempoMap)
    {
        if (tempoMap == null || tempoMap.Count == 0)
            return Math.Max(0.0, quarterPos) * 0.5;

        double targetQuarter = Math.Max(0.0, quarterPos);
        double seconds = 0.0;
        Gp5TimelineTempoPoint current = tempoMap[0];

        for (int i = 1; i < tempoMap.Count; i++)
        {
            Gp5TimelineTempoPoint next = tempoMap[i];
            if (targetQuarter <= next.quarterPos)
            {
                seconds += Math.Max(0.0, targetQuarter - current.quarterPos) * (60.0 / Math.Max(1.0, current.bpm));
                return seconds;
            }

            seconds += Math.Max(0.0, next.quarterPos - current.quarterPos) * (60.0 / Math.Max(1.0, current.bpm));
            current = next;
        }

        seconds += Math.Max(0.0, targetQuarter - current.quarterPos) * (60.0 / Math.Max(1.0, current.bpm));
        return seconds;
    }

    private bool TryGetCurrentArrangementCachePart(out RocksmithCachedArrangementPart part)
    {
        part = null;
        if (currentSongEntry == null ||
            currentSongEntry.PrimaryNotationKind != SongNotationSourceKind.ArrangementCache ||
            string.IsNullOrWhiteSpace(currentSongEntry.PrimaryNotationPath))
        {
            return false;
        }

        string selectedPartId = selectedMusicXmlPartId ?? string.Empty;
        if (!string.IsNullOrWhiteSpace(selectedPartId) &&
            ArrangementCacheSongLoader.TryLoadArrangementPartByPartId(currentSongEntry.PrimaryNotationPath, selectedPartId, out _, out part))
        {
            return part != null;
        }

        string selectedGroupId = !string.IsNullOrWhiteSpace(selectedPartId)
            ? GetArrangementGroupIdFromPartId(selectedPartId)
            : string.Empty;
        if (!string.IsNullOrWhiteSpace(selectedGroupId) &&
            ArrangementCacheSongLoader.TryLoadArrangementPartByGroupId(currentSongEntry.PrimaryNotationPath, selectedGroupId, out _, out part))
        {
            return part != null;
        }

        if (currentSongPartSummaries != null && midiTrackIndex >= 0 && midiTrackIndex < currentSongPartSummaries.Count)
        {
            MusicXmlLoader.MusicXmlPartSummary summary = currentSongPartSummaries[midiTrackIndex];
            if (summary != null)
            {
                if (!string.IsNullOrWhiteSpace(summary.PartId) &&
                    ArrangementCacheSongLoader.TryLoadArrangementPartByPartId(currentSongEntry.PrimaryNotationPath, summary.PartId, out _, out part))
                {
                    return part != null;
                }

                if (!string.IsNullOrWhiteSpace(summary.GroupId) &&
                    ArrangementCacheSongLoader.TryLoadArrangementPartByGroupId(currentSongEntry.PrimaryNotationPath, summary.GroupId, out _, out part))
                {
                    return part != null;
                }
            }
        }

        return false;
    }

    private void AddArrangementTimelineSections(List<RocksmithCachedSectionData> sections, float duration)
    {
        if (sections == null)
            return;

        int index = 0;
        float lastTime = -1f;
        for (int i = 0; i < sections.Count; i++)
        {
            RocksmithCachedSectionData source = sections[i];
            if (source == null || source.timeSeconds < 0f)
                continue;

            float startTime = Mathf.Max(0f, source.timeSeconds);
            if (startTime + 0.001f < lastTime)
                continue;

            if (songTimelineSections.Count > 0 &&
                Mathf.Abs(songTimelineSections[songTimelineSections.Count - 1].startTime - startTime) <= 0.001f)
            {
                songTimelineSections[songTimelineSections.Count - 1].name = FormatTimelineSectionName(source.name, index);
                continue;
            }

            songTimelineSections.Add(new SongTimelineSectionData
            {
                index = index,
                name = FormatTimelineSectionName(source.name, index),
                startTime = startTime,
                endTime = Mathf.Max(startTime + 0.05f, duration)
            });
            index++;
            lastTime = startTime;
        }
    }

    private void AddArcadeTimelineSections(float duration)
    {
        if (currentArcadePracticeSections == null || currentArcadePracticeSections.Count == 0)
            return;

        for (int i = 0; i < currentArcadePracticeSections.Count; i++)
        {
            ArcadePracticeSectionData source = currentArcadePracticeSections[i];
            if (source == null || source.endTime <= source.startTime)
                continue;

            songTimelineSections.Add(new SongTimelineSectionData
            {
                index = songTimelineSections.Count,
                name = FormatTimelineSectionName(source.name, songTimelineSections.Count),
                startTime = Mathf.Max(0f, source.startTime),
                endTime = Mathf.Max(source.startTime + 0.05f, source.endTime)
            });
        }
    }

    private void AddGeneratedTimelineSections(float duration)
    {
        if (tabSections == null || tabSections.Count == 0)
            return;

        int sectionStride = Mathf.Max(1, Mathf.RoundToInt(16f / Mathf.Max(0.01f, GetEffectiveTabSectionDuration())));
        for (int i = 0; i < tabSections.Count; i += sectionStride)
        {
            TabSectionData source = tabSections[i];
            if (source == null)
                continue;

            float endTime = i + sectionStride < tabSections.Count
                ? tabSections[i + sectionStride].startTime
                : Mathf.Max(duration, source.endTime);

            songTimelineSections.Add(new SongTimelineSectionData
            {
                index = songTimelineSections.Count,
                name = $"Part {songTimelineSections.Count + 1}",
                startTime = Mathf.Max(0f, source.startTime),
                endTime = Mathf.Max(source.startTime + 0.05f, endTime)
            });
        }
    }

    private void NormalizeTimelineSectionEnds(float duration)
    {
        if (songTimelineSections == null || songTimelineSections.Count == 0)
            return;

        songTimelineSections = songTimelineSections
            .Where(section => section != null && section.startTime >= 0f)
            .OrderBy(section => section.startTime)
            .ToList();

        for (int i = 0; i < songTimelineSections.Count; i++)
        {
            SongTimelineSectionData section = songTimelineSections[i];
            section.index = i;
            float nextStart = i + 1 < songTimelineSections.Count
                ? songTimelineSections[i + 1].startTime
                : duration;
            section.endTime = Mathf.Max(section.startTime + 0.05f, nextStart);
        }
    }

    private float GetTimelineLastEndTime()
    {
        if (songTimelineSections == null || songTimelineSections.Count == 0)
            return 0f;

        float max = 0f;
        for (int i = 0; i < songTimelineSections.Count; i++)
        {
            SongTimelineSectionData section = songTimelineSections[i];
            if (section != null)
                max = Mathf.Max(max, section.endTime, section.startTime);
        }

        return max;
    }

    private static string FormatTimelineSectionName(string rawName, int index)
    {
        string normalized = string.IsNullOrWhiteSpace(rawName)
            ? $"Part {index + 1}"
            : rawName.Trim().Replace('_', ' ').Replace('-', ' ');

        normalized = Regex.Replace(normalized, @"\s+", " ");
        if (normalized.Length == 0)
            return $"Part {index + 1}";

        string key = normalized.Replace(" ", string.Empty).ToLowerInvariant();
        switch (key)
        {
            case "noguitar":
                return "No Guitar";
            case "postvs":
                return "Post Verse";
            case "prevs":
                return "Pre Verse";
            case "modverse":
                return "Verse";
            case "modchorus":
                return "Chorus";
        }

        TextInfo textInfo = CultureInfo.InvariantCulture.TextInfo;
        return textInfo.ToTitleCase(normalized.ToLowerInvariant());
    }
}
